insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d4000000-0000-0000-0000-000000000001', 'mrcp2', '5094d3e0-ad2e-4496-b90d-d6633dcb6866',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d4000000-0000-0000-0000-000000000001', 'A', 'Endoscopic pneumatic dilation of the lower oesophageal sphincter', false, 'Ruled out as the preferred next step because prior surgery and fundoplication cause periesophageal fibrosis that both reduces the efficacy of dilation as salvage therapy and increases the risk of perforation compared with a fresh endoscopic myotomy plane.', 1),
('d4000000-0000-0000-0000-000000000001', 'B', 'Refer for peroral endoscopic myotomy (POEM) to create a fresh, more extensive myotomy', true, 'Correct. Objective evidence of persistent outflow obstruction (elevated IRP, poor column emptying) after a failed Heller myotomy warrants endoscopic salvage. POEM allows a new myotomy in a plane not previously operated on, often extending further onto the gastric side, and has become an effective salvage option after failed surgical myotomy.', 2),
('d4000000-0000-0000-0000-000000000001', 'C', 'Repeat laparoscopic Heller myotomy', false, 'Ruled out because redo surgical myotomy is technically difficult due to adhesions and fibrosis from the first operation, carries higher morbidity, and is generally reserved for after endoscopic salvage options have failed.', 3),
('d4000000-0000-0000-0000-000000000001', 'D', 'Endoscopic botulinum toxin injection into the lower oesophageal sphincter', false, 'Ruled out because its effect is short-lived (weeks to a few months) and it is not an appropriate durable strategy in a fit patient who is a candidate for definitive endoscopic or surgical salvage.', 4),
('d4000000-0000-0000-0000-000000000001', 'E', 'Oesophagectomy', false, $x$Ruled out as a first step because this is a radical, high-morbidity intervention reserved for end-stage ('burnt-out') achalasia unresponsive to all other measures, not for a first failure of Heller myotomy.$x$, 5),
('d4000000-0000-0000-0000-000000000002', 'A', 'Continue escalating the dose of loperamide long-term', false, 'Ruled out because a ceiling effect has already been reached without benefit, it does not address the pain/urgency component, and supratherapeutic doses carry a risk of cardiac conduction abnormalities (QT prolongation, torsades).', 1),
('d4000000-0000-0000-0000-000000000002', 'B', 'Switch to an alternative tricyclic antidepressant such as imipramine', false, 'Ruled out because sedation and anticholinergic effects are a class effect of tricyclics; switching within the same drug class is unlikely to resolve the tolerability problem, and a different mechanism of action should be tried instead.', 2),
('d4000000-0000-0000-0000-000000000002', 'C', 'Start eluxadoline', true, 'Correct. Eluxadoline is a mixed mu/kappa-opioid receptor agonist and delta-opioid receptor antagonist licensed for IBS-D uncontrolled by conventional therapy, reducing stool frequency, urgency and abdominal pain. It is contraindicated in patients without a gallbladder, with alcohol excess, or a history of pancreatitis/sphincter of Oddi dysfunction (risk of pancreatitis) - all of which are absent here, making it an appropriate and safe next choice.', 3),
('d4000000-0000-0000-0000-000000000002', 'D', 'Refer for faecal microbiota transplantation', false, 'Ruled out because this is not an evidence-based or licensed treatment for IBS-D; its established role is in recurrent Clostridioides difficile infection, not functional bowel disease.', 4),
('d4000000-0000-0000-0000-000000000002', 'E', 'Start regular strong opioid analgesia for symptom control', false, 'Ruled out because opioids have no role in IBS management and risk causing narcotic bowel syndrome, worsening long-term gut function.', 5),
('d4000000-0000-0000-0000-000000000003', 'A', 'Increase the domperidone dose further', false, 'Ruled out because her baseline QTc is already prolonged (440ms) and MHRA guidance restricts domperidone to the lowest effective dose for the shortest duration because of arrhythmia risk.', 1),
('d4000000-0000-0000-0000-000000000003', 'B', 'Restart regular metoclopramide for long-term use', false, $x$Ruled out because MHRA guidance limits metoclopramide to a maximum of 5 days' use due to the risk of extrapyramidal effects and tardive dyskinesia, particularly important given she has already had a dystonic reaction.$x$, 2),
('d4000000-0000-0000-0000-000000000003', 'C', 'Endoscopic pyloric botulinum toxin injection', false, 'Ruled out because, despite theoretical rationale and popularity, randomised controlled trials show no significant benefit over sham injection for gastroparesis symptoms, and it is not recommended by guidelines.', 3),
('d4000000-0000-0000-0000-000000000003', 'D', 'Start high-dose proton pump inhibitor therapy', false, 'Ruled out because this targets acid-related reflux symptoms, not the underlying gastric dysmotility, and has no proven role in controlling gastroparesis-related vomiting.', 4),
('d4000000-0000-0000-0000-000000000003', 'E', 'Refer for consideration of gastric electrical stimulation', true, 'Correct. Gastric electrical stimulation is reserved for diabetic gastroparesis refractory to dietary and pharmacological prokinetic therapy, particularly for predominantly vomiting/nausea symptoms, and is delivered through a specialist tertiary unit.', 5),
('d4000000-0000-0000-0000-000000000004', 'A', 'Subtotal colectomy', false, 'Ruled out because surgery is generally avoided in chronic intestinal pseudo-obstruction due to poor outcomes and progression of dysmotility in the remaining bowel; it is reserved for specific complications such as perforation or volvulus.', 1),
('d4000000-0000-0000-0000-000000000004', 'B', 'Exploratory laparotomy to identify a transition point', false, 'Ruled out because imaging has already confirmed no mechanical obstruction; there is no transition point to find, and repeated laparotomy risks adhesions that worsen dysmotility.', 2),
('d4000000-0000-0000-0000-000000000004', 'C', 'Long-term regular opioid analgesia for abdominal pain', false, 'Ruled out because opioids further impair gastrointestinal motility and can precipitate or worsen pseudo-obstructive episodes (narcotic bowel).', 3),
('d4000000-0000-0000-0000-000000000004', 'D', 'Refer to a specialist intestinal failure/nutrition team for enteral support, progressing to home parenteral nutrition if needed, while avoiding surgery', true, 'Correct. Chronic intestinal pseudo-obstruction reflects a neuromuscular gut motility disorder (here from scleroderma visceral myopathy) that mimics mechanical obstruction radiologically but has no anatomical transition point. Surgery does not correct the underlying dysmotility and can worsen outcomes, so nutritional support via a specialist team is the mainstay once weight loss develops despite medical therapy.', 4),
('d4000000-0000-0000-0000-000000000004', 'E', 'Recommend a high-fibre diet', false, 'Ruled out because high fibre is poorly tolerated in severe gut dysmotility, can worsen bloating, and risks bolus obstruction; a low-residue, nutritionally supported approach is preferred.', 5),
('d4000000-0000-0000-0000-000000000005', 'A', 'Add a night-time H2-receptor antagonist to the existing twice-daily PPI, reserving anti-reflux surgery given the risk of severe dysphagia from fundoplication in aperistaltic disease', true, 'Correct. Scleroderma oesophageal disease causes absent peristalsis with a hypotensive LES, producing severe reflux; this combination makes full fundoplication high-risk for severe obstructive dysphagia, since the oesophagus cannot generate the peristaltic force to overcome the wrap. Adding a bedtime H2-receptor antagonist can target nocturnal acid breakthrough despite twice-daily PPI dosing.', 1),
('d4000000-0000-0000-0000-000000000005', 'B', 'Refer for laparoscopic Nissen (360-degree) fundoplication', false, $x$Ruled out because a full fundoplication is relatively contraindicated with absent peristalsis, as it can cause severe obstructive dysphagia and bolus impaction from the oesophagus's inability to overcome the wrap's resistance.$x$, 2),
('d4000000-0000-0000-0000-000000000005', 'C', 'Stop PPI therapy and rely on alginate/antacid therapy alone', false, 'Ruled out because this is inadequate for LA grade C oesophagitis complicated by aspiration; potent acid suppression should be maintained or intensified, not withdrawn.', 3),
('d4000000-0000-0000-0000-000000000005', 'D', 'Proceed directly to oesophagectomy', false, 'Ruled out because this is a radical, high-morbidity intervention with no indication here (no stricture, dysplasia or malignancy), reserved for refractory end-stage disease.', 4),
('d4000000-0000-0000-0000-000000000005', 'E', 'Refer for peroral endoscopic myotomy (POEM)', false, 'Ruled out because POEM divides the lower oesophageal sphincter to relieve outflow obstruction in achalasia; here the sphincter is already hypotensive/incompetent, so myotomy would worsen reflux.', 5),
('d4000000-0000-0000-0000-000000000006', 'A', 'Increase the dose of the stimulant laxative further', false, 'Ruled out because he is already on maximal tolerated standard laxative therapy without response, and guidelines recommend a PAMORA as the next step rather than further laxative escalation.', 1),
('d4000000-0000-0000-0000-000000000006', 'B', 'Switch oxycodone to an equivalent dose of morphine', false, 'Ruled out because opioid switching does not reliably resolve opioid-induced constipation, which is a class effect of mu-opioid receptor agonism in the gut, and would not address the constipation while risking inadequate analgesia during conversion.', 2),
('d4000000-0000-0000-0000-000000000006', 'C', 'Start a peripherally-acting mu-opioid receptor antagonist (e.g., naloxegol or methylnaltrexone)', true, 'Correct. Opioid-induced constipation refractory to optimised conventional laxative therapy (osmotic plus stimulant) is an indication for a peripherally-acting mu-opioid receptor antagonist, which blocks gut opioid receptors without significantly crossing the blood-brain barrier, preserving central analgesia.', 3),
('d4000000-0000-0000-0000-000000000006', 'D', 'Perform manual evacuation', false, 'Ruled out because rectal examination has already excluded faecal impaction, so this is not indicated.', 4),
('d4000000-0000-0000-0000-000000000006', 'E', 'Stop opioids and switch to NSAID-based analgesia', false, 'Ruled out because this is inappropriate for metastatic bone pain requiring strong opioid control, and there is no need to stop effective analgesia when a specific effective anti-constipation therapy is available.', 5),
('d4000000-0000-0000-0000-000000000007', 'A', 'Increase the frequency of endoscopic dilation alone without escalating anti-inflammatory therapy', false, 'Ruled out because this addresses the mechanical stricture but not the persistent underlying eosinophilic inflammation driving recurrent stricture formation, risking repeated bolus impaction or perforation.', 1),
('d4000000-0000-0000-0000-000000000007', 'B', 'Trial a six-food elimination diet as monotherapy', false, 'Ruled out as the best next step because, while a reasonable adjunctive strategy, it does not have an immediate impact on an established fibrostenotic stricture and does not represent adequate escalation in confirmed treatment-refractory, biopsy-active disease.', 2),
('d4000000-0000-0000-0000-000000000007', 'C', 'Stop budesonide and start long-term high-dose oral prednisolone', false, 'Ruled out because escalation to a targeted biologic is preferred over long-term systemic corticosteroids, which carry cumulative toxicity for a chronic condition.', 3),
('d4000000-0000-0000-0000-000000000007', 'D', 'Start dupilumab in addition to endoscopic dilation of the stricture', true, 'Correct. Eosinophilic oesophagitis refractory to topical corticosteroids, with confirmed adherence and persistent histological activity, is an indication for biologic therapy such as dupilumab (an anti-IL-4-receptor-alpha monoclonal antibody), used alongside continued endoscopic management of any stricture.', 4),
('d4000000-0000-0000-0000-000000000007', 'E', 'Proceed to oesophagectomy', false, 'Ruled out because this is excessive; there is no indication for surgery in eosinophilic oesophagitis strictures, which are managed with endoscopic dilation and escalated medical therapy.', 5),
('d4000000-0000-0000-0000-000000000008', 'A', 'Switch oral vancomycin to oral fidaxomicin', false, 'Ruled out because fidaxomicin is not proven in fulminant/severe-complicated CDI and is not the standard escalation here; its main role is reducing recurrence risk in non-fulminant disease.', 1),
('d4000000-0000-0000-0000-000000000008', 'B', 'Add IV metronidazole to the existing oral vancomycin', true, 'Correct. Progression to fulminant C. difficile colitis (systemic toxicity with impending toxic megacolon) warrants combination therapy with oral (or per-rectum if ileus present) vancomycin plus IV metronidazole, alongside early surgical review.', 2),
('d4000000-0000-0000-0000-000000000008', 'C', 'Discontinue vancomycin and proceed urgently to faecal microbiota transplantation', false, 'Ruled out because FMT is not appropriate as first-line rescue therapy in acute fulminant CDI; it is used for recurrent, non-fulminant CDI after standard therapy has already failed.', 3),
('d4000000-0000-0000-0000-000000000008', 'D', 'Continue the current management unchanged and reassess in 5 days', false, 'Ruled out because there are evolving signs of fulminant colitis (rising lactate, worsening distension, systemic toxicity) requiring escalation now, not watchful waiting.', 4),
('d4000000-0000-0000-0000-000000000008', 'E', 'Proceed immediately to subtotal colectomy regardless of surgical risk', false, 'Ruled out because surgery is reserved for perforation, refractory toxic megacolon, or multi-organ failure despite maximal medical therapy; escalating medical therapy is appropriate first here given no perforation, though close surgical liaison should continue.', 5),
('d4000000-0000-0000-0000-000000000009', 'A', 'Urgent transjugular intrahepatic portosystemic shunt (TIPS)', true, 'Correct. TIPS is indicated for variceal bleeding that is refractory to, or recurs despite, combined pharmacological and endoscopic therapy, as in this case with failure of two endoscopic attempts and ongoing instability.', 1),
('d4000000-0000-0000-0000-000000000009', 'B', 'Balloon tamponade (Sengstaken-Blakemore tube) as definitive management', false, 'Ruled out because balloon tamponade is a temporising measure only, used to stabilise before definitive intervention, not definitive treatment itself, given the risk of mucosal ischaemia/perforation with prolonged inflation.', 2),
('d4000000-0000-0000-0000-000000000009', 'C', 'Repeat band ligation for a third attempt', false, 'Ruled out because endoscopic therapy has already failed twice; continued attempts without escalation risk ongoing exsanguination.', 3),
('d4000000-0000-0000-0000-000000000009', 'D', 'Switch terlipressin to octreotide and continue medical management alone', false, 'Ruled out because medical therapy alone is insufficient for ongoing refractory bleeding requiring definitive haemostatic intervention.', 4),
('d4000000-0000-0000-0000-000000000009', 'E', 'Urgent liver transplantation', false, 'Ruled out as an immediate haemostatic measure because it is not available emergently; TIPS is the appropriate bridging/definitive intervention for refractory variceal bleeding, with transplant workup a separate longer-term consideration.', 5),
('d4000000-0000-0000-0000-000000000010', 'A', 'Proceed immediately to right hemicolectomy', false, 'Ruled out because surgery is reserved for complications (perforation, necrosis, uncontrolled bleeding, deterioration despite medical therapy), not first-line for uncomplicated typhlitis.', 1),
('d4000000-0000-0000-0000-000000000010', 'B', 'Withhold antibiotics until blood culture results return', false, 'Ruled out because broad-spectrum antibiotics should be given empirically immediately in a neutropenic septic patient, not delayed pending cultures.', 2),
('d4000000-0000-0000-0000-000000000010', 'C', 'Administer granulocyte colony-stimulating factor as the priority intervention', false, 'Ruled out because, while G-CSF may be a reasonable adjunct to hasten neutrophil recovery, it is not the priority intervention over antibiotics and supportive care.', 3),
('d4000000-0000-0000-0000-000000000010', 'D', 'Urgent colonoscopy to confirm the diagnosis endoscopically', false, 'Ruled out because endoscopy is contraindicated in suspected neutropenic enterocolitis due to a high risk of perforating a friable, inflamed bowel wall; diagnosis is made on clinical and CT grounds.', 4),
('d4000000-0000-0000-0000-000000000010', 'E', 'Continue conservative management with broad-spectrum antibiotics, bowel rest and supportive care, reserving surgery for specific complications', true, 'Correct. Neutropenic enterocolitis (typhlitis) is generally managed medically first, with surgery reserved for perforation, uncontrolled haemorrhage, or clinical deterioration despite maximal medical therapy.', 5),
('d4000000-0000-0000-0000-000000000011', 'A', 'Immediate surgical drainage as first-line treatment', false, 'Ruled out because surgery is not needed for an uncomplicated amoebic liver abscess responding to medical therapy; it is reserved for rupture or failure of medical management.', 1),
('d4000000-0000-0000-0000-000000000011', 'B', 'Broad-spectrum antibiotics alone without anti-amoebic therapy', false, 'Ruled out because this would not treat the causative organism; the travel history and positive serology strongly support amoebic aetiology requiring specific therapy.', 2),
('d4000000-0000-0000-0000-000000000011', 'C', 'Oral metronidazole (or tinidazole), followed by a luminal agent such as paromomycin or diloxanide furoate', true, 'Correct. Amoebic liver abscess is treated medically with a tissue-active nitroimidazole followed by a luminal agent to eradicate intestinal cyst carriage, since metronidazole/tinidazole alone does not reliably clear luminal infection.', 3),
('d4000000-0000-0000-0000-000000000011', 'D', 'Metronidazole alone without a subsequent luminal agent', false, 'Ruled out because metronidazole does not reliably eradicate intraluminal (colonic) cyst carriage, risking relapse or transmission; a luminal agent should follow.', 4),
('d4000000-0000-0000-0000-000000000011', 'E', 'Percutaneous aspiration as the sole treatment without antimicrobial therapy', false, 'Ruled out because aspiration alone without anti-amoebic drugs is inadequate and the abscess would likely recur; drainage is reserved as an adjunct for large or complicated abscesses, not as monotherapy.', 5),
('d4000000-0000-0000-0000-000000000012', 'A', 'No prophylaxis needed as the current episode has resolved', false, 'Ruled out because secondary prophylaxis is indicated after any SBP episode given the very high recurrence risk without it.', 1),
('d4000000-0000-0000-0000-000000000012', 'B', 'Start long-term prophylactic antibiotics (e.g., oral norfloxacin or ciprofloxacin) and evaluate for liver transplantation', true, 'Correct. Secondary antibiotic prophylaxis is indicated after any episode of SBP given a very high (up to 70%) one-year recurrence rate without it, and recurrent SBP is a marker of advanced liver disease warranting transplant assessment.', 2),
('d4000000-0000-0000-0000-000000000012', 'C', 'Therapeutic paracentesis alone with no antibiotic prophylaxis', false, 'Ruled out because this does not address recurrence risk, which specifically requires secondary antibiotic prophylaxis.', 3),
('d4000000-0000-0000-0000-000000000012', 'D', 'Only start prophylactic antibiotics if ascitic protein is below 15g/L', false, 'Ruled out because this describes a criterion for primary prophylaxis (never had SBP); secondary prophylaxis is indicated for anyone with a prior SBP episode regardless of protein level.', 4),
('d4000000-0000-0000-0000-000000000012', 'E', 'Commence long-term IV antibiotics rather than oral therapy', false, 'Ruled out because this is unnecessary and impractical for long-term outpatient prophylaxis; an oral fluoroquinolone (or alternative) is standard.', 5),
('d4000000-0000-0000-0000-000000000013', 'A', 'Continue IV corticosteroids alone for a further 4-5 days before considering escalation', false, 'Ruled out because day-3 criteria predicting a high colectomy risk should prompt escalation now, not a delay that risks worse outcomes.', 1),
('d4000000-0000-0000-0000-000000000013', 'B', 'Switch to oral prednisolone and discharge for outpatient follow-up', false, 'Ruled out because this represents ongoing acute severe colitis meeting escalation criteria, not a step-down/discharge scenario.', 2),
('d4000000-0000-0000-0000-000000000013', 'C', 'Proceed directly to emergency colectomy without a trial of medical rescue therapy', false, 'Ruled out because, in the absence of toxic megacolon, perforation or haemodynamic instability, a trial of medical rescue therapy is appropriate first, with surgery as backup if this fails.', 3),
('d4000000-0000-0000-0000-000000000013', 'D', 'Add oral mesalazine to the IV corticosteroids', false, 'Ruled out because oral 5-ASA has no meaningful role in the acute management of severe colitis and would not address failure to respond to IV steroids.', 4),
('d4000000-0000-0000-0000-000000000013', 'E', 'Commence rescue therapy with infliximab or ciclosporin, while continuing surgical team involvement', true, 'Correct. The Oxford (Travis) criteria at day 3 (stool frequency >8/day, or 3-8/day with CRP >45) predict a high likelihood of needing colectomy without further intervention, and identify patients who should be escalated to medical rescue therapy or considered for surgery.', 5),
('d4000000-0000-0000-0000-000000000014', 'A', 'Urgent resuscitation, broad-spectrum IV antibiotics and antifungal cover, nil by mouth, and urgent surgical/thoracic referral', true, 'Correct. This is Boerhaave syndrome (spontaneous oesophageal perforation) with signs of sepsis and instability, a surgical emergency requiring urgent resuscitation, broad-spectrum antimicrobial cover and surgical/thoracic input for repair or endoscopic stenting.', 1),
('d4000000-0000-0000-0000-000000000014', 'B', 'Conservative management alone with IV antibiotics and nil by mouth, without surgical or interventional referral', false, 'Ruled out because conservative management is appropriate only for small, contained, clinically stable perforations without sepsis; here the patient is haemodynamically unstable with mediastinal contamination, requiring urgent surgical/interventional input.', 2),
('d4000000-0000-0000-0000-000000000014', 'C', 'Urgent upper GI endoscopy without prior surgical involvement to confirm the diagnosis', false, 'Ruled out because the diagnosis is already confirmed on CT; endoscopy risks extending the perforation and should not precede surgical/thoracic team involvement.', 3),
('d4000000-0000-0000-0000-000000000014', 'D', 'Insertion of a nasogastric tube for gastric decompression as the priority intervention', false, 'Ruled out because blind NG tube insertion risks worsening the perforation and is not the priority ahead of resuscitation and definitive surgical referral.', 4),
('d4000000-0000-0000-0000-000000000014', 'E', 'Discharge with oral antibiotics for presumed severe gastritis', false, 'Ruled out because a missed oesophageal perforation carries very high untreated mortality and requires urgent inpatient management.', 5),
('d4000000-0000-0000-0000-000000000015', 'A', 'Increase the infliximab dose or shorten the dosing interval', false, 'Ruled out because dose intensification is most useful for pharmacokinetic failure (low trough without significant antibodies), not for confirmed high-titre antibody-driven immunogenic failure, where the antibodies accelerate drug clearance regardless of dose.', 1),
('d4000000-0000-0000-0000-000000000015', 'B', 'Add azathioprine to the current infliximab regimen without changing biologic', false, 'Ruled out because, while starting an immunomodulator early alongside a biologic can reduce the risk of immunogenicity developing, established high-titre antibodies with confirmed drug failure usually require switching agents rather than simply adding an immunomodulator to a failing drug.', 2),
('d4000000-0000-0000-0000-000000000015', 'C', 'Continue the current infliximab regimen and repeat drug levels in 3 months', false, 'Ruled out because it is inappropriate to continue an ineffective, immunogenic biologic while active, biopsy-confirmed disease progresses.', 3),
('d4000000-0000-0000-0000-000000000015', 'D', 'Switch to an alternative biologic agent', true, 'Correct. This is immunogenic (antibody-mediated) loss of response: a low trough level with high-titre anti-drug antibodies. Dose intensification is unlikely to help in this situation, so switching to a different agent is preferred.', 4),
('d4000000-0000-0000-0000-000000000015', 'E', 'Increase the infliximab dose while co-administering high-dose corticosteroids to overcome antibody formation', false, 'Ruled out because there is no evidence-based role for this combination approach; corticosteroids are not appropriate for long-term maintenance and do not reverse established immunogenicity.', 5),
('d4000000-0000-0000-0000-000000000016', 'A', 'Tofacitinib', false, 'Ruled out because, while effective for UC, JAK inhibitors carry safety signals for thromboembolism, cardiovascular events and malignancy, and current guidance recommends caution/avoidance in women planning pregnancy or during pregnancy itself.', 1),
('d4000000-0000-0000-0000-000000000016', 'B', 'Vedolizumab', true, 'Correct. Vedolizumab is a gut-selective anti-integrin biologic effective for thiopurine-refractory UC. Its gut-selective mechanism limits systemic immunosuppression, giving it a favourable safety profile for a patient planning pregnancy.', 2),
('d4000000-0000-0000-0000-000000000016', 'C', 'Continue azathioprine at a higher dose', false, 'Ruled out because she is already at a therapeutic dose with confirmed adequate 6-TGN levels and ongoing endoscopically active disease, so a further increase above an already therapeutic level is unlikely to help and risks toxicity.', 3),
('d4000000-0000-0000-0000-000000000016', 'D', 'Long-term maintenance with intermittent oral corticosteroid courses as required', false, 'Ruled out because this is an inappropriate long-term strategy given the risk of steroid dependence and known adverse effects with cumulative steroid use, and conflicts with her wish to avoid ongoing steroid exposure.', 4),
('d4000000-0000-0000-0000-000000000016', 'E', 'Proceed directly to colectomy', false, 'Ruled out as premature because she has not yet trialled biologic therapy; colectomy is reserved for medically refractory disease after appropriate escalation, or for specific complications, not simply thiopurine failure in this setting.', 5),
('d4000000-0000-0000-0000-000000000017', 'A', 'Increase the azathioprine dose alone without adding a biologic', false, 'Ruled out because thiopurines have only modest efficacy for fistula healing and are not the most effective option; anti-TNF therapy has significantly better evidence for complex perianal fistulising disease.', 1),
('d4000000-0000-0000-0000-000000000017', 'B', 'Remove the seton promptly after abscess drainage to allow the fistula to heal spontaneously', false, 'Ruled out because setons should remain in place to allow ongoing drainage and prevent recurrent abscess formation while medical therapy takes effect; premature removal risks abscess recurrence.', 2),
('d4000000-0000-0000-0000-000000000017', 'C', 'Commence anti-TNF therapy (e.g., infliximab) in combination with the surgical seton', true, $x$Correct. Combined medical (anti-TNF) and surgical (seton drainage) therapy is the most effective strategy for complex perianal fistulising Crohn's disease, with anti-TNF agents having the strongest evidence base for fistula healing.$x$, 3),
('d4000000-0000-0000-0000-000000000017', 'D', 'Oral metronidazole monotherapy as definitive long-term treatment', false, 'Ruled out because antibiotics provide useful adjunctive symptomatic benefit but are not effective as sole definitive long-term therapy, and carry cumulative toxicity (peripheral neuropathy) with prolonged use.', 4),
('d4000000-0000-0000-0000-000000000017', 'E', 'Proceed to proctectomy with permanent stoma as first-line management', false, 'Ruled out as an overly aggressive first step, reserved for medically refractory, severely symptomatic complex fistulising disease after appropriate trials of combined medical-surgical therapy.', 5),
('d4000000-0000-0000-0000-000000000018', 'A', 'Continue further isolated 2-week antibiotic courses reactively whenever symptoms recur', false, 'Ruled out because this has already proven inadequate (rapid relapse each time) and does not address the antibiotic-dependent pattern requiring a maintenance strategy.', 1),
('d4000000-0000-0000-0000-000000000018', 'B', 'Start anti-TNF biologic therapy as the immediate next step', false, $x$Ruled out because biologics are generally reserved for antibiotic-refractory pouchitis (failing to respond to antibiotics at all) or Crohn's-like disease of the pouch, not first-line for antibiotic-dependent (antibiotic-responsive) pouchitis where maintenance strategies should be tried first.$x$, 2),
('d4000000-0000-0000-0000-000000000018', 'C', 'Proceed to pouch excision with a permanent ileostomy', false, 'Ruled out as excessive at this stage; this is reserved for pouchitis refractory to maintenance medical therapy and biologics, or structural/functional pouch failure.', 3),
('d4000000-0000-0000-0000-000000000018', 'D', 'Commence long-term maintenance therapy (e.g., a probiotic such as VSL#3, or continuous/rotating low-dose antibiotics) rather than repeated short antibiotic courses', true, 'Correct. This pattern - response to antibiotics but rapid relapse each time treatment stops - defines antibiotic-dependent pouchitis, which requires a maintenance strategy rather than repeated isolated short courses.', 4),
('d4000000-0000-0000-0000-000000000018', 'E', 'Repeat pouchoscopy in 3 months without any change in treatment', false, 'Ruled out because ongoing symptomatic relapsing disease requires a change in management strategy now, not simply repeat surveillance.', 5),
('d4000000-0000-0000-0000-000000000019', 'A', 'Stop adalimumab immediately at 26 weeks to reduce fetal drug exposure', false, 'Ruled out because stopping biologic therapy in a well-controlled patient risks disease flare, which is itself associated with worse pregnancy outcomes than continued anti-TNF therapy.', 1),
('d4000000-0000-0000-0000-000000000019', 'B', 'Switch to certolizumab pegol only after delivery, having stopped all anti-TNF therapy now', false, 'Ruled out because switching biologics unnecessarily mid-pregnancy in a stable, well patient risks losing disease control without clear benefit, and stopping therapy altogether is not advised regardless.', 2),
('d4000000-0000-0000-0000-000000000019', 'C', 'Continue adalimumab but delay all vaccinations in the infant until 12 months of age regardless of vaccine type', false, 'Ruled out as overly restrictive; the specific advice is to avoid live vaccines in the infant for the first 6 months, while inactivated vaccines can proceed on the normal schedule.', 3),
('d4000000-0000-0000-0000-000000000019', 'D', 'Advise that pregnancy is contraindicated while on biologic therapy and recommend termination', false, 'Ruled out because biologic therapy is not a contraindication to pregnancy, and disease control during pregnancy is actively recommended.', 4),
('d4000000-0000-0000-0000-000000000019', 'E', 'Continue adalimumab throughout pregnancy at the standard dosing schedule', true, 'Correct. Maintaining disease remission during pregnancy is associated with better maternal and fetal outcomes than stopping effective therapy, so anti-TNF biologics are generally continued through pregnancy in stable patients, with live vaccines avoided in the infant for the first 6 months given transplacental drug transfer.', 5),
('d4000000-0000-0000-0000-000000000020', 'A', 'Endoscopic balloon dilation of the stricture', true, $x$Correct. Short, focal, accessible, non-penetrating Crohn's strictures can often be managed with endoscopic balloon dilation, avoiding surgical bowel resection and the risk of short bowel syndrome from repeated operations.$x$, 1),
('d4000000-0000-0000-0000-000000000020', 'B', 'Proceed directly to surgical resection', false, 'Ruled out because surgery is more appropriate for long, multiple, or complicated (fistulising/abscess-associated) strictures, or after failure of endoscopic therapy; a short accessible uncomplicated stricture is suitable first for balloon dilation.', 2),
('d4000000-0000-0000-0000-000000000020', 'C', 'Escalate anti-inflammatory (biologic) therapy alone with no mechanical intervention', false, 'Ruled out because the stricture is described as non-inflammatory/fibrotic in a patient already in biochemical remission on biologic therapy; escalating anti-inflammatory therapy will not resolve a predominantly fibrotic mechanical stricture.', 3),
('d4000000-0000-0000-0000-000000000020', 'D', 'Manage conservatively with a low-residue diet alone, with no endoscopic or surgical intervention', false, 'Ruled out because, while a reasonable adjunctive symptomatic measure, this does not address the underlying structural stricture causing obstructive symptoms.', 4),
('d4000000-0000-0000-0000-000000000020', 'E', 'Insert a self-expanding metal stent across the stricture', false, $x$Ruled out because this is not standard practice for benign Crohn's strictures (more relevant to malignant colorectal obstruction); balloon dilation is the preferred endoscopic technique for short benign Crohn's strictures.$x$, 5),
('d4000000-0000-0000-0000-000000000021', 'A', 'Refer for proctocolectomy given any finding of dysplasia in longstanding colitis', false, 'Ruled out as overly aggressive; colectomy is reserved for dysplasia that is not endoscopically resectable, is multifocal, is associated with flat/invisible dysplasia, or is high-grade in flat mucosa - not for a completely resected, well-demarcated adenoma-like lesion.', 1),
('d4000000-0000-0000-0000-000000000021', 'B', 'No further surveillance is needed given clear resection margins', false, 'Ruled out because ongoing surveillance colonoscopy, often at a shortened interval, is still required after resection of a dysplastic lesion given the underlying field risk of longstanding colitis.', 2),
('d4000000-0000-0000-0000-000000000021', 'C', 'Repeat biopsy of the resection site only, with no surveillance of the remaining colon', false, 'Ruled out because surveillance should assess the entire colon given the field risk in longstanding extensive colitis, not just the resection site.', 3),
('d4000000-0000-0000-0000-000000000021', 'D', 'Continue endoscopic surveillance at a shortened interval', true, 'Correct. Endoscopically resectable, adenoma-like dysplastic lesions with clear margins and no flat dysplasia elsewhere can be managed with continued surveillance rather than colectomy, unlike non-resectable, flat, or multifocal dysplasia.', 4),
('d4000000-0000-0000-0000-000000000021', 'E', 'Start chemoprevention with high-dose 5-ASA as an alternative to ongoing surveillance', false, 'Ruled out because 5-ASA may have a modest chemopreventive role but does not replace the need for ongoing endoscopic surveillance in this high-risk situation.', 5),
('d4000000-0000-0000-0000-000000000022', 'A', 'Refer for formal liver transplantation assessment', true, 'Correct. Recurrent overt hepatic encephalopathy despite optimal medical therapy (lactulose plus rifaximin) is a recognised indication for liver transplantation assessment, independent of the calculated MELD score.', 1),
('d4000000-0000-0000-0000-000000000022', 'B', 'Further increase the lactulose dose beyond current titration', false, 'Ruled out because it is already optimally titrated to target stool frequency; further increases risk dehydration and hypernatraemia and can paradoxically worsen encephalopathy without added benefit.', 2),
('d4000000-0000-0000-0000-000000000022', 'C', 'Initiate dietary protein restriction to reduce ammoniagenic substrate', false, 'Ruled out because protein restriction is not recommended in cirrhosis due to the risk of worsening malnutrition and sarcopenia, which independently worsens outcomes; adequate protein intake is instead recommended.', 3),
('d4000000-0000-0000-0000-000000000022', 'D', 'Add long-term oral neomycin instead of rifaximin', false, 'Ruled out because neomycin carries significant risk of nephrotoxicity and ototoxicity with prolonged use and is not preferred over rifaximin, which has a superior long-term safety profile.', 4),
('d4000000-0000-0000-0000-000000000022', 'E', 'Reassure that no further intervention is needed since precipitants have been excluded on each admission', false, 'Ruled out because recurrent overt HE despite optimal standard therapy is a significant marker of disease severity requiring formal escalation, not reassurance alone.', 5),
('d4000000-0000-0000-0000-000000000023', 'A', 'Continue albumin infusion alone without vasoconstrictor therapy', false, 'Ruled out because albumin alone is insufficient once a volume expansion trial has failed to improve creatinine; combination with a vasoconstrictor is required.', 1),
('d4000000-0000-0000-0000-000000000023', 'B', 'Start renal replacement therapy immediately as the first-line intervention', false, 'Ruled out because RRT may be used as a bridge to transplantation if pharmacological therapy fails, but terlipressin/albumin is trialled first unless there are other standard indications for urgent dialysis.', 2),
('d4000000-0000-0000-0000-000000000023', 'C', 'Start terlipressin plus IV human albumin solution', true, 'Correct. This presentation - AKI with normal urinalysis/ultrasound, no nephrotoxic exposure, and failure of a volume expansion trial after diuretic withdrawal, with sepsis/SBP excluded - meets criteria for hepatorenal syndrome-AKI, for which first-line pharmacological therapy is a vasoconstrictor plus albumin.', 3),
('d4000000-0000-0000-0000-000000000023', 'D', 'Recommence diuretic therapy to promote natriuresis', false, 'Ruled out because diuretics are contraindicated in AKI/HRS as they would further worsen renal perfusion and volume status.', 4),
('d4000000-0000-0000-0000-000000000023', 'E', 'Perform a further diagnostic ascitic tap only, with no change in treatment', false, 'Ruled out because SBP has already been reasonably excluded and this presentation, following failure of a volume-expansion trial with normal urinalysis/ultrasound, meets criteria for HRS-AKI requiring specific vasoconstrictor/albumin therapy now.', 5),
('d4000000-0000-0000-0000-000000000024', 'A', 'Reassure and repeat FibroScan in 3 years with no other action', false, 'Ruled out because confirmed advanced fibrosis requires specialist input and more intensive intervention/surveillance now, not simple reassurance with delayed follow-up.', 1),
('d4000000-0000-0000-0000-000000000024', 'B', 'Commence high-dose vitamin E monotherapy as the definitive treatment', false, 'Ruled out because vitamin E has evidence specifically in biopsy-proven MASH in non-diabetic patients, not as monotherapy in a diabetic patient with advanced fibrosis, where weight loss and specialist-directed therapy take priority.', 2),
('d4000000-0000-0000-0000-000000000024', 'C', 'Advise that no further intervention is needed since ALT is only mildly elevated', false, 'Ruled out because ALT correlates poorly with fibrosis severity; this patient has non-invasively confirmed advanced fibrosis, which is the key prognostic marker, not the ALT level.', 3),
('d4000000-0000-0000-0000-000000000024', 'D', 'Proceed directly to liver transplant assessment', false, 'Ruled out as premature; F3 fibrosis (advanced but not cirrhotic/decompensated) does not meet transplant criteria, and the priority is intensified risk-factor modification and specialist follow-up.', 4),
('d4000000-0000-0000-0000-000000000024', 'E', 'Refer to hepatology for consideration of further staging and pharmacological therapy, and intensify structured weight-management support', true, 'Correct. Confirmed advanced fibrosis (F3) on non-invasive testing warrants specialist hepatology input and more intensive intervention (aiming for at least 7-10% weight loss, considering pharmacological or bariatric options given his diabetes/obesity), rather than continued simple lifestyle advice alone.', 5),
('d4000000-0000-0000-0000-000000000025', 'A', 'Increase the azathioprine dose alone without reintroducing steroids', false, 'Ruled out because azathioprine monotherapy at an already therapeutic dose has failed to maintain remission; increasing it further without reintroducing steroids is unlikely to adequately re-induce remission during an active relapse.', 1),
('d4000000-0000-0000-0000-000000000025', 'B', 'Reintroduce corticosteroid therapy in combination with continued azathioprine', true, 'Correct. Relapse after steroid withdrawal is common in autoimmune hepatitis and indicates steroid-dependence; standard management is to reintroduce corticosteroid therapy in combination with an immunomodulator to reinduce remission.', 2),
('d4000000-0000-0000-0000-000000000025', 'C', 'Switch azathioprine to mycophenolate mofetil monotherapy without steroids', false, 'Ruled out because mycophenolate is established as second-line steroid-sparing therapy, typically combined with steroids, not as monotherapy to reinduce remission during an active relapse.', 3),
('d4000000-0000-0000-0000-000000000025', 'D', 'No treatment change needed; recheck bloods in 3 months', false, 'Ruled out because confirmed biochemical and histological relapse requires treatment now; ongoing untreated interface hepatitis risks progression to cirrhosis.', 4),
('d4000000-0000-0000-0000-000000000025', 'E', 'Proceed to liver transplantation assessment', false, 'Ruled out as premature; this represents a treatable relapse responsive to standard re-induction therapy, not decompensated/end-stage disease unresponsive to medical therapy.', 5),
('d4000000-0000-0000-0000-000000000026', 'A', 'A copper chelating agent (trientine or penicillamine)', true, $x$Correct. Copper chelating agents are first-line for symptomatic Wilson's disease, promoting urinary copper excretion; trientine is often preferred due to a better side-effect profile than penicillamine.$x$, 1),
('d4000000-0000-0000-0000-000000000026', 'B', 'Zinc salts as sole initial therapy', false, 'Ruled out because zinc acts by blocking intestinal copper absorption, useful for maintenance therapy or presymptomatic/pregnant patients, but is not preferred initial treatment for symptomatic disease given its much slower onset of action compared with chelation therapy.', 2),
('d4000000-0000-0000-0000-000000000026', 'C', 'Liver transplantation', false, 'Ruled out because this is reserved for acute liver failure or decompensated cirrhosis unresponsive to medical therapy, not mild, non-decompensated hepatic dysfunction that should respond to chelation therapy.', 3),
('d4000000-0000-0000-0000-000000000026', 'D', 'Tetrathiomolybdate as first-line standard therapy', false, $x$Ruled out because this is a less widely available agent mainly studied for neurological Wilson's disease to avoid paradoxical neurological worsening seen with penicillamine, not standard first-line for predominantly hepatic presentations.$x$, 4),
('d4000000-0000-0000-0000-000000000026', 'E', 'No pharmacological treatment needed as she is asymptomatic neurologically', false, 'Ruled out because she has confirmed symptomatic (hepatic) disease requiring treatment regardless of neurological symptom absence, to prevent progression to liver failure/cirrhosis and neurological disease.', 5),
('d4000000-0000-0000-0000-000000000027', 'A', 'Proceed immediately to TIPS as first-line therapy without a trial of anticoagulation', false, 'Ruled out because TIPS/angioplasty is reserved as a step-up therapy for those failing or progressing despite anticoagulation, per a stepwise treatment algorithm.', 1),
('d4000000-0000-0000-0000-000000000027', 'B', 'Commence therapeutic anticoagulation and treat the underlying myeloproliferative disorder', true, 'Correct. Anticoagulation is first-line initial management in Budd-Chiari syndrome, particularly with preserved liver function, alongside treating the underlying prothrombotic disorder; TIPS or other interventional/surgical decompression is reserved as step-up therapy for non-responders.', 2),
('d4000000-0000-0000-0000-000000000027', 'C', 'Liver transplantation as first-line management', false, 'Ruled out because this is reserved for fulminant hepatic failure or those who fail all other interventional/medical therapy with progressive decompensation, not first-line with preserved liver function.', 3),
('d4000000-0000-0000-0000-000000000027', 'D', 'Withhold anticoagulation given the risk of variceal bleeding until endoscopy is performed', false, 'Ruled out because anticoagulation should not be unduly delayed, as it is the cornerstone of Budd-Chiari management and is generally started promptly with appropriate precautions rather than withheld outright.', 4),
('d4000000-0000-0000-0000-000000000027', 'E', 'Diuretics alone for ascites control without addressing the underlying venous thrombosis', false, 'Ruled out because this treats a symptom without addressing the causative hepatic venous outflow obstruction, risking progression to liver failure if the thrombosis is not treated.', 5),
('d4000000-0000-0000-0000-000000000028', 'A', 'Continue regular large-volume paracentesis with albumin cover as the only long-term strategy, with no consideration of TIPS', false, 'Ruled out because TIPS should be considered/offered in eligible patients with refractory ascites, reducing paracentesis frequency and improving outcomes compared with repeated LVP alone in appropriately selected patients.', 1),
('d4000000-0000-0000-0000-000000000028', 'B', 'Restart diuretics at a lower dose alongside fluid restriction', false, 'Ruled out because diuretic-induced hyponatraemia and hyperkalaemia already prompted cessation; this defines diuretic-intractable ascites, and restarting is likely to reproduce electrolyte complications.', 2),
('d4000000-0000-0000-0000-000000000028', 'C', 'Peritoneovenous shunt as first-line management', false, 'Ruled out because this has largely been abandoned due to high complication rates and inferior outcomes compared with TIPS or LVP, and is not standard first-line therapy where TIPS is available.', 3),
('d4000000-0000-0000-0000-000000000028', 'D', 'Refer for liver transplantation only, deferring any further ascites-specific intervention', false, 'Ruled out because, while transplant assessment is appropriate to pursue long-term, it does not address the immediate need for effective ascites control, for which TIPS can serve as an effective bridging therapy.', 4),
('d4000000-0000-0000-0000-000000000028', 'E', 'Refer for consideration of transjugular intrahepatic portosystemic shunt (TIPS)', true, 'Correct. This is diuretic-intractable refractory ascites (requiring frequent large-volume paracentesis) in a patient without contraindications (no prior HE, preserved cardiac function, acceptable Child-Pugh class), meeting criteria for TIPS referral.', 5),
('d4000000-0000-0000-0000-000000000029', 'A', 'Reassure that dietary adherence alone will resolve symptoms over time', false, 'Ruled out because type II refractory coeliac disease reflects a clonal T-cell disorder that does not respond to dietary measures alone and requires specialist management and lymphoma surveillance.', 1),
('d4000000-0000-0000-0000-000000000029', 'B', 'Trial a further, more stringent gluten-free diet review only, with no other intervention', false, 'Ruled out because adherence has already been confirmed as strict; the aberrant clonal intraepithelial lymphocyte population is not diet-responsive.', 2),
('d4000000-0000-0000-0000-000000000029', 'C', 'Commence long-term high-dose oral corticosteroids alone as definitive lifelong therapy without further specialist staging', false, 'Ruled out because, while steroids may give initial symptomatic benefit, definitive management requires specialist staging and surveillance for lymphoma alongside consideration of more targeted therapies, not corticosteroids in isolation without surveillance.', 3),
('d4000000-0000-0000-0000-000000000029', 'D', 'Refer to a specialist coeliac/small bowel centre for staging and consideration of immunosuppressive or targeted therapy', true, 'Correct. Refractory coeliac disease type II is a pre-malignant clonal T-cell disorder carrying significant risk of progression to enteropathy-associated T-cell lymphoma, requiring specialist staging (including capsule endoscopy/MR enterography for lymphoma surveillance) and consideration of therapies such as corticosteroids or, in severe cases, cladribine/stem cell transplantation.', 4),
('d4000000-0000-0000-0000-000000000029', 'E', 'Diagnose non-coeliac gluten sensitivity and stop further investigation', false, 'Ruled out because biopsy and flow cytometry findings specifically confirm refractory coeliac disease type II, a distinct diagnosis with malignant potential requiring active specialist management.', 5),
('d4000000-0000-0000-0000-000000000030', 'A', 'Increase parenteral nutrition frequency to 7 nights a week rather than seeking to reduce dependency', false, 'Ruled out because this moves in the wrong direction; the goal in eligible patients is to reduce PN dependency where possible using intestinal rehabilitation strategies.', 1),
('d4000000-0000-0000-0000-000000000030', 'B', 'Proceed to intestinal transplantation as the next step', false, 'Ruled out because this is reserved for irreversible intestinal failure with life-threatening complications of parenteral nutrition unresponsive to intestinal rehabilitation measures, not the appropriate next step before trialling teduglutide.', 2),
('d4000000-0000-0000-0000-000000000030', 'C', 'Trial of teduglutide, a GLP-2 analogue', true, 'Correct. Teduglutide promotes intestinal mucosal adaptation and absorptive capacity, reducing parenteral nutrition/fluid requirements in appropriately selected patients with short bowel syndrome-associated intestinal failure who remain dependent on PN despite optimised standard measures.', 3),
('d4000000-0000-0000-0000-000000000030', 'D', 'Increase soluble fibre and anti-motility drug doses further as the primary strategy', false, 'Ruled out because these agents have already been optimised without reducing PN dependency; a physiological/trophic approach targeting intestinal adaptation is the appropriate escalation.', 4),
('d4000000-0000-0000-0000-000000000030', 'E', 'Surgical bowel-lengthening procedure (e.g., the STEP procedure) as the next step', false, 'Ruled out because this is primarily used in paediatric short bowel syndrome with dilated bowel amenable to lengthening, and is not the standard next step in this adult patient without a specific anatomical indication.', 5),
('d4000000-0000-0000-0000-000000000031', 'A', 'Loperamide as first-line definitive therapy', false, 'Ruled out because this provides symptomatic benefit for stool frequency/urgency but does not address the underlying bile acid malabsorption mechanism; a bile acid sequestrant is the specific first-line treatment.', 1),
('d4000000-0000-0000-0000-000000000031', 'B', 'High-dose proton pump inhibitor therapy', false, 'Ruled out because there is no established role for acid suppression in bile acid diarrhoea, which is a colonic/bile acid-mediated process, not related to gastric acid.', 2),
('d4000000-0000-0000-0000-000000000031', 'C', 'Rifaximin for presumed small intestinal bacterial overgrowth', false, 'Ruled out because the confirmed diagnosis here, via SeHCAT, is bile acid malabsorption post-cholecystectomy, not SIBO; rifaximin is not the specific treatment for this confirmed diagnosis.', 3),
('d4000000-0000-0000-0000-000000000031', 'D', 'A bile acid sequestrant, such as colesevelam or colestyramine', true, 'Correct. Bile acid diarrhoea, confirmed here by a markedly reduced SeHCAT 7-day retention, is treated first-line with a bile acid sequestrant to bind excess bile acids in the colon and reduce diarrhoea.', 4),
('d4000000-0000-0000-0000-000000000031', 'E', 'Total colectomy for symptom control', false, 'Ruled out because this is grossly excessive for a condition effectively managed with bile acid sequestrant therapy.', 5),
('d4000000-0000-0000-0000-000000000032', 'A', 'Continue indefinite courses of the same antibiotic at higher doses each time symptoms recur', false, 'Ruled out because repeated same-agent courses without addressing predisposing factors or considering rotation increases resistance risk and does not address the underlying dysmotility driving recurrence.', 1),
('d4000000-0000-0000-0000-000000000032', 'B', 'Proceed to long-term total parenteral nutrition', false, 'Ruled out as excessive; recurrent SIBO with a treatable underlying driver does not require parenteral nutrition, which is reserved for genuine intestinal failure.', 2),
('d4000000-0000-0000-0000-000000000032', 'C', 'Address the underlying predisposing dysmotility where possible and use rotating or cyclical antibiotic courses for recurrent SIBO', true, 'Correct. Recurrent SIBO is common when an underlying predisposing cause (here, diabetic autonomic neuropathy-related dysmotility) is not addressed; management should target both the bacterial overgrowth (with rotating antibiotic classes to reduce resistance risk) and the underlying driver.', 3),
('d4000000-0000-0000-0000-000000000032', 'D', 'Strict lifelong low-FODMAP diet as sole therapy without antibiotics', false, 'Ruled out because dietary modification can help symptomatically, but recurrent, breath-test-confirmed SIBO with a clear predisposing cause should also involve antibiotic therapy and addressing the motility disorder, not diet alone.', 4),
('d4000000-0000-0000-0000-000000000032', 'E', 'Small bowel resection to remove the affected segment', false, 'Ruled out because SIBO here is due to a functional motility disorder, not a structural/anatomical abnormality requiring surgical resection.', 5),
('d4000000-0000-0000-0000-000000000033', 'A', 'A short course (7-10 days) of oral amoxicillin alone', false, $x$Ruled out because this is inadequate both in duration and CNS penetration for Whipple's disease with neurological involvement, which requires prolonged treatment with CNS-penetrant agents.$x$, 1),
('d4000000-0000-0000-0000-000000000033', 'B', 'Induction therapy with a CNS-penetrant antibiotic regimen (e.g., IV ceftriaxone) for 2-4 weeks, followed by prolonged oral maintenance therapy for at least 1 year', true, $x$Correct. Whipple's disease with evidence of CNS involvement requires prolonged treatment starting with a CNS-penetrant antibiotic to prevent relapse and progression, followed by extended oral maintenance therapy such as co-trimoxazole.$x$, 2),
('d4000000-0000-0000-0000-000000000033', 'C', 'No antibiotic therapy needed; manage with nutritional support alone', false, $x$Ruled out because Whipple's disease is a chronic bacterial infection that is fatal if untreated, particularly with CNS involvement, requiring specific prolonged antimicrobial therapy.$x$, 3),
('d4000000-0000-0000-0000-000000000033', 'D', 'High-dose corticosteroids as sole therapy for the arthralgia and systemic symptoms', false, 'Ruled out because this would not treat the underlying infection and could worsen outcomes by further immunosuppressing a patient with active infection.', 4),
('d4000000-0000-0000-0000-000000000033', 'E', 'A single-dose antibiotic regimen, as used for eradicating other gut pathogens', false, $x$Ruled out because Whipple's disease requires a much more prolonged treatment course due to relapse risk, particularly with neurological involvement, unlike short-course eradication regimens for other GI infections.$x$, 5),
('d4000000-0000-0000-0000-000000000034', 'A', 'Continue intramuscular hydroxocobalamin loading until neurological symptoms plateau, followed by lifelong maintenance injections every 2-3 months', true, 'Correct. Pernicious anaemia with neurological involvement (subacute combined degeneration of the cord) requires ongoing parenteral B12 loading until neurological improvement plateaus, then indefinite maintenance injections, since intrinsic factor-mediated malabsorption cannot be reliably overcome by oral replacement.', 1),
('d4000000-0000-0000-0000-000000000034', 'B', 'Switch to oral B12 replacement once the initial loading dose is given', false, 'Ruled out because oral B12 replacement is generally reserved for dietary deficiency without malabsorption; pernicious anaemia with neurological involvement requires ongoing parenteral replacement.', 2),
('d4000000-0000-0000-0000-000000000034', 'C', 'Give a single further IM injection only, with no planned maintenance therapy', false, 'Ruled out because pernicious anaemia is a lifelong condition requiring indefinite maintenance IM B12 injections after the loading phase, not a single additional dose.', 3),
('d4000000-0000-0000-0000-000000000034', 'D', 'Start folic acid replacement alone without further B12 therapy', false, 'Ruled out because correcting folate without adequately replacing B12 risks precipitating or worsening subacute combined degeneration of the cord; B12 must be adequately replaced first or alongside folate.', 4),
('d4000000-0000-0000-0000-000000000034', 'E', 'Defer further treatment until formal neurology assessment and MRI spine are completed', false, 'Ruled out because the diagnosis is already clear and treatment should not be delayed pending further imaging, which is not required to confirm this clinical diagnosis.', 5),
('d4000000-0000-0000-0000-000000000035', 'A', 'Switch to a low-fat diet as the primary intervention instead of optimising enzyme replacement', false, 'Ruled out because fat restriction is generally not recommended in chronic pancreatitis with PERT; adequate fat intake with optimised enzyme therapy is preferred to prevent further nutritional decline.', 1),
('d4000000-0000-0000-0000-000000000035', 'B', 'Increase PERT dose without changing the timing/technique of administration', false, 'Ruled out because dosing technique is a common cause of inadequate response and should be corrected in addition to considering dose increases.', 2),
('d4000000-0000-0000-0000-000000000035', 'C', 'Discontinue PERT and proceed directly to total pancreatectomy', false, 'Ruled out as a drastic, unnecessary step; optimising medical therapy should be tried and exhausted before considering major surgery, which is not indicated for isolated exocrine insufficiency management.', 3),
('d4000000-0000-0000-0000-000000000035', 'D', 'Add a bile acid sequestrant to reduce steatorrhoea', false, 'Ruled out because bile acid sequestrants target a different mechanism (bile acid diarrhoea) and could actually worsen fat malabsorption by further binding bile acids needed for fat digestion.', 4),
('d4000000-0000-0000-0000-000000000035', 'E', 'Optimise PERT technique and dosing - taking enzymes throughout the meal including snacks, increasing dose if needed, and adding a proton pump inhibitor', true, 'Correct. A common reason for apparent PERT failure is incorrect administration technique; enzymes should be taken throughout the meal (not only at the start) and with snacks, and co-prescribing a PPI reduces gastric acid degradation of the enzymes, improving efficacy.', 5),
('d4000000-0000-0000-0000-000000000036', 'A', 'Proceed immediately to open surgical necrosectomy as first-line', false, 'Ruled out because open necrosectomy carries higher morbidity/mortality than a step-up minimally invasive approach and is now reserved for cases where percutaneous/endoscopic strategies are not feasible or fail.', 1),
('d4000000-0000-0000-0000-000000000036', 'B', 'Continue antibiotics alone with no drainage or debridement', false, 'Ruled out because infected necrosis generally requires source control (drainage/debridement) in addition to antibiotics; antibiotics alone are insufficient for confirmed infected necrosis causing ongoing sepsis.', 2),
('d4000000-0000-0000-0000-000000000036', 'C', 'Delay any intervention until the collection is definitely walled-off for a further 4 weeks regardless of clinical status', false, 'Ruled out because, while delaying intervention is preferred where clinically feasible in sterile necrosis, this collection is already walled-off and infected with clinical deterioration, warranting intervention now rather than further delay.', 3),
('d4000000-0000-0000-0000-000000000036', 'D', $x$A minimally invasive 'step-up' approach, starting with percutaneous or endoscopic transluminal catheter drainage, escalating to minimally invasive necrosectomy only if drainage is insufficient$x$, true, 'Correct. The step-up approach (drainage first, escalating to minimally invasive necrosectomy if needed, with open necrosectomy reserved for failure of these measures) reduces morbidity and mortality compared with primary open surgical necrosectomy for infected pancreatic necrosis.', 4),
('d4000000-0000-0000-0000-000000000036', 'E', 'Immediate cholecystectomy as the priority intervention over managing the infected necrosis', false, 'Ruled out because cholecystectomy is important to prevent recurrent gallstone pancreatitis but should be deferred, with priority given to managing the acute infected necrotic collection first.', 5),
('d4000000-0000-0000-0000-000000000037', 'A', $x$Whipple's procedure (pancreaticoduodenectomy)$x$, false, 'Ruled out because autoimmune pancreatitis is a steroid-responsive inflammatory condition, not a malignancy, and biopsy has already excluded cancer; surgery is reserved for diagnostic uncertainty where malignancy cannot be excluded.', 1),
('d4000000-0000-0000-0000-000000000037', 'B', 'ERCP with pancreatic duct stenting as definitive treatment', false, 'Ruled out because, while duct stenting may sometimes assist biliary decompression while awaiting steroid response, steroids are the definitive treatment for the underlying disease, not duct stenting alone.', 2),
('d4000000-0000-0000-0000-000000000037', 'C', 'A trial of oral corticosteroids', true, 'Correct. Oral corticosteroids are first-line induction therapy for autoimmune pancreatitis, typically producing a rapid clinical, biochemical and radiological response in IgG4-related type 1 disease, with tapering over several months and consideration of steroid-sparing maintenance for relapsing disease.', 3),
('d4000000-0000-0000-0000-000000000037', 'D', 'Long-term rituximab as first-line initial therapy', false, 'Ruled out because rituximab has an established role for relapsing/steroid-refractory disease or steroid-sparing maintenance, but oral corticosteroids remain first-line induction therapy in a treatment-naive presentation.', 4),
('d4000000-0000-0000-0000-000000000037', 'E', 'Observation alone with repeat imaging in 6 months', false, 'Ruled out because significant obstructive jaundice requires treatment, and a highly steroid-responsive condition should be treated promptly rather than observed.', 5),
('d4000000-0000-0000-0000-000000000038', 'A', 'A plastic biliary stent', true, 'Correct. Plastic stents are preferred for short-term preoperative decompression in a patient proceeding to surgery within a few weeks, avoiding difficulties that metal stents can pose during subsequent surgical resection, and being more cost-effective for short-term use.', 1),
('d4000000-0000-0000-0000-000000000038', 'B', 'A self-expanding metal stent (SEMS)', false, 'Ruled out as the routine preoperative choice because SEMS are preferred for longer-term or palliative decompression given their greater patency duration, but are generally avoided before planned resectional surgery in the near term as they can complicate the surgical field.', 2),
('d4000000-0000-0000-0000-000000000038', 'C', 'No stent; proceed directly to surgery despite the degree of hyperbilirubinaemia', false, 'Ruled out because with this degree of severe hyperbilirubinaemia and associated symptoms, decompression is generally undertaken before major surgery, and even where drainage is used, stent type selection still matters.', 3),
('d4000000-0000-0000-0000-000000000038', 'D', 'A covered metal stent left in place indefinitely with no plan for surgery', false, 'Ruled out because this is inconsistent with the case; the patient is being planned for curative resection with defined preoperative decompression, not indefinite palliative stenting.', 4),
('d4000000-0000-0000-0000-000000000038', 'E', 'Percutaneous transhepatic biliary drainage as the routine first-choice approach over endoscopic stenting', false, 'Ruled out because endoscopic (ERCP-guided) stenting is generally preferred first-line where technically feasible, with percutaneous drainage reserved for cases where endoscopic access fails or is not possible.', 5),
('d4000000-0000-0000-0000-000000000039', 'A', 'Immediate liver transplantation without further evaluation', false, 'Ruled out as premature; dominant strictures can often be managed endoscopically, and transplantation is reserved for decompensated disease or, after full staging, confirmed early-stage cholangiocarcinoma meeting specific protocol criteria.', 1),
('d4000000-0000-0000-0000-000000000039', 'B', 'Endoscopic balloon dilation of the dominant stricture at ERCP, with or without short-term stenting', true, 'Correct. Endoscopic balloon dilation relieves biliary obstruction and reduces the risk of complications such as cholangitis, while brush cytology/FISH obtained at the same procedure helps exclude cholangiocarcinoma, which must always be considered with a new dominant stricture in PSC.', 2),
('d4000000-0000-0000-0000-000000000039', 'C', 'Long-term biliary stenting with a permanent indwelling metal stent', false, 'Ruled out because permanent metal stents are generally avoided in benign PSC-related dominant strictures due to stent-related complications and difficulty with future endoscopic access/surveillance.', 3),
('d4000000-0000-0000-0000-000000000039', 'D', 'Observation alone with no endoscopic intervention until cytology results are available', false, 'Ruled out because this is an inappropriate delay in a patient with symptomatic obstruction and risk of cholangitis; dilation should proceed at the same ERCP procedure alongside sampling for malignancy.', 4),
('d4000000-0000-0000-0000-000000000039', 'E', 'Commence ursodeoxycholic acid at high dose as the definitive treatment for the stricture', false, 'Ruled out because ursodeoxycholic acid does not treat a mechanically obstructing dominant stricture, which requires endoscopic intervention, and high-dose ursodeoxycholic acid has been associated with harm in some PSC trials.', 5),
('d4000000-0000-0000-0000-000000000040', 'A', 'Repeat ERCP with further duct clearance and re-stenting', false, 'Ruled out because this has already been tried with only transient benefit; evidence supports earlier surgical referral over repeated endoscopic attempts once endoscopic therapy has failed in a dilated duct.', 1),
('d4000000-0000-0000-0000-000000000040', 'B', 'Coeliac plexus block/neurolysis as the next definitive step', false, 'Ruled out because this provides only temporary analgesic benefit and does not address the underlying obstructive ductal pathology; surgical decompression is preferred given the dilated, obstructed duct amenable to drainage.', 2),
('d4000000-0000-0000-0000-000000000040', 'C', 'Total pancreatectomy with islet autotransplantation as the next step', false, 'Ruled out because this more radical option is generally reserved for small-duct disease not amenable to drainage procedures, or after failure of duct-drainage surgery; here a less radical drainage operation is preferred first.', 3),
('d4000000-0000-0000-0000-000000000040', 'D', 'Continue escalating opioid analgesia alone with no interventional/surgical referral', false, 'Ruled out as an inappropriate long-term strategy given the risk of opioid dependence and the availability of an effective definitive surgical option for this anatomy.', 4),
('d4000000-0000-0000-0000-000000000040', 'E', 'Refer for surgical drainage/decompression (e.g., lateral pancreaticojejunostomy)', true, 'Correct. Failure of endoscopic therapy to provide durable pain relief, in the context of a dilated duct amenable to drainage, is an indication for surgical decompression, which provides more durable pain relief than repeated endoscopic intervention in this anatomy.', 5),
('d4000000-0000-0000-0000-000000000041', 'A', $x$Discharge and arrange elective cholecystectomy in 3 months' time$x$, false, 'Ruled out because delaying cholecystectomy this long carries a significant risk of recurrent gallstone-related complications in the interim; guidance favours same-admission or early cholecystectomy for mild pancreatitis.', 1),
('d4000000-0000-0000-0000-000000000041', 'B', 'No cholecystectomy needed, as the current episode has resolved', false, 'Ruled out because cholecystectomy is indicated to prevent recurrent gallstone-related pancreatitis and biliary complications, as the underlying gallstone disease has not been addressed.', 2),
('d4000000-0000-0000-0000-000000000041', 'C', 'Proceed to ERCP with sphincterotomy alone as definitive treatment, without cholecystectomy', false, 'Ruled out because ERCP/sphincterotomy may reduce recurrent pancreatitis risk in patients unfit for surgery, but is not a substitute for cholecystectomy in a fit patient with gallbladder stones in situ.', 3),
('d4000000-0000-0000-0000-000000000041', 'D', 'Arrange laparoscopic cholecystectomy during this same admission', true, 'Correct. Current guidance recommends cholecystectomy within 2 weeks, ideally during the index admission, for mild gallstone pancreatitis, to reduce the risk of recurrent biliary events before an interval operation.', 4),
('d4000000-0000-0000-0000-000000000041', 'E', 'Delay cholecystectomy until 6 weeks post-discharge to allow complete resolution of pancreatic inflammation, as for severe pancreatitis', false, 'Ruled out because this delayed approach applies specifically to severe/necrotising pancreatitis; for mild pancreatitis without local complications, same-admission or early cholecystectomy is preferred.', 5),
('d4000000-0000-0000-0000-000000000042', 'A', 'Administer prophylactic IV broad-spectrum antibiotics to prevent pancreatitis', false, 'Ruled out because antibiotics are used to prevent post-ERCP cholangitis, not specifically to prevent post-ERCP pancreatitis, which has a different pathophysiology.', 1),
('d4000000-0000-0000-0000-000000000042', 'B', 'Use of a needle-knife pre-cut sphincterotomy early and routinely to facilitate cannulation', false, 'Ruled out because needle-knife pre-cutting is generally reserved as a rescue technique for failed standard cannulation, and if used inappropriately/early is associated with increased, not decreased, pancreatitis risk.', 2),
('d4000000-0000-0000-0000-000000000042', 'C', 'Prophylactic IV corticosteroids prior to the procedure', false, 'Ruled out because corticosteroids have not been shown to reduce post-ERCP pancreatitis risk and are not part of standard prophylaxis.', 3),
('d4000000-0000-0000-0000-000000000042', 'D', 'Routine prophylactic therapeutic-dose anticoagulation', false, 'Ruled out because this has no role in preventing post-ERCP pancreatitis and would introduce unnecessary bleeding risk during an endoscopic procedure.', 4),
('d4000000-0000-0000-0000-000000000042', 'E', 'Administer a rectal NSAID (e.g., diclofenac or indomethacin) peri-procedurally, alongside consideration of prophylactic pancreatic duct stent placement', true, 'Correct. Rectal NSAIDs are the best-evidenced pharmacological measure to reduce post-ERCP pancreatitis risk, and prophylactic pancreatic duct stenting is an additional evidence-based measure in high-risk patients such as this one.', 5),
('d4000000-0000-0000-0000-000000000043', 'A', 'Oesophagectomy as first-line treatment', false, 'Ruled out because this is reserved for submucosal invasion, lymph node involvement, or endoscopically unresectable disease; endoscopic therapy is preferred first-line for mucosal disease given comparable oncological outcomes with much lower morbidity.', 1),
('d4000000-0000-0000-0000-000000000043', 'B', $x$Endoscopic mucosal resection (EMR) of the visible nodular lesion, followed by radiofrequency ablation (RFA) of the remaining flat Barrett's segment$x$, true, $x$Correct. A visible/nodular lesion should first undergo EMR both to remove it and to obtain accurate histological staging (excluding submucosal invasion), followed by RFA to treat the remaining flat dysplastic segment; combined endoscopic therapy is now standard for Barrett's-associated high-grade dysplasia confined to the mucosa.$x$, 2),
('d4000000-0000-0000-0000-000000000043', 'C', 'Radiofrequency ablation alone without prior resection of the visible nodular lesion', false, 'Ruled out because RFA alone is appropriate for flat dysplasia without a visible lesion; a nodular lesion should first undergo EMR for accurate staging before ablating the remaining flat segment.', 3),
('d4000000-0000-0000-0000-000000000043', 'D', 'Continued endoscopic surveillance alone with repeat biopsies in 6 months, without endoscopic treatment', false, 'Ruled out because confirmed high-grade dysplasia with a visible lesion carries a high risk of progression to invasive cancer and should be treated, not merely monitored.', 4),
('d4000000-0000-0000-0000-000000000043', 'E', 'Photodynamic therapy as first-line ablative treatment', false, $x$Ruled out because this has been largely superseded by RFA, which has a better safety/efficacy profile for ablating Barrett's dysplasia.$x$, 5),
('d4000000-0000-0000-0000-000000000044', 'A', 'Refer for consideration of laparoscopic anti-reflux surgery (fundoplication)', true, 'Correct. Objectively confirmed reflux (weakly acidic, with a positive symptom association) refractory to optimised PPI therapy, with a normal endoscopy and a clear mechanical/reflux-based explanation for ongoing symptoms, is an indication to consider anti-reflux surgery.', 1),
('d4000000-0000-0000-0000-000000000044', 'B', 'Further increase the PPI dose beyond twice daily', false, 'Ruled out because the study shows normal acid exposure with symptoms driven by weakly acidic (non-acid) reflux, which would not be expected to improve with further acid suppression.', 2),
('d4000000-0000-0000-0000-000000000044', 'C', 'Diagnose functional heartburn and manage with a low-dose antidepressant alone, with no consideration of anti-reflux surgery', false, 'Ruled out because functional heartburn is characterised by a negative symptom association with reflux and normal reflux burden; here there is a positive symptom association with reflux episodes, indicating true reflux-related symptoms.', 3),
('d4000000-0000-0000-0000-000000000044', 'D', 'Repeat upper GI endoscopy immediately as the next investigation', false, 'Ruled out because endoscopy has already been performed and was normal, and pH-impedance data already provide the key next-step information.', 4),
('d4000000-0000-0000-0000-000000000044', 'E', 'Trial of an H2-receptor antagonist added at night instead of considering surgery', false, 'Ruled out because the issue is weakly acidic (non-acid-dominant) reflux, and additional acid suppression would not be expected to resolve non-acid reflux-driven symptoms.', 5),
('d4000000-0000-0000-0000-000000000045', 'A', 'Proceed directly to total gastrectomy for symptom control', false, 'Ruled out as excessive and outdated; acid hypersecretion is now managed with high-dose PPI therapy, and surgery (when appropriate) targets resection of the gastrinoma itself after localisation, not the stomach.', 1),
('d4000000-0000-0000-0000-000000000045', 'B', 'Screen for MEN1 only if there is a family history, and otherwise proceed straight to surgery without further localisation imaging', false, 'Ruled out because localisation imaging should be performed regardless of MEN1 status before surgery is planned, and MEN1 screening is generally recommended in all patients with a new gastrinoma diagnosis regardless of family history.', 2),
('d4000000-0000-0000-0000-000000000045', 'C', 'Cross-sectional and somatostatin receptor imaging to localise the gastrinoma, alongside continued high-dose PPI therapy', true, 'Correct. After biochemical confirmation of Zollinger-Ellison syndrome, localisation imaging (cross-sectional imaging plus somatostatin receptor scintigraphy/PET) is required to assess for resectable disease and exclude metastases, before considering surgery, while high-dose PPI controls acid-related symptoms.', 3),
('d4000000-0000-0000-0000-000000000045', 'D', 'Standard-dose PPI therapy alone with no further imaging or surgical consideration', false, 'Ruled out because standard-dose PPI is often insufficient for the higher acid output in ZES, and localisation imaging/surgical assessment is an important next step for potentially curable localised disease.', 4),
('d4000000-0000-0000-0000-000000000045', 'E', 'Empirical somatostatin analogue therapy as first-line management, without imaging localisation', false, 'Ruled out because somatostatin analogues have a role in metastatic/unresectable disease for symptom control, but the priority in a new diagnosis is tumour localisation to assess for potentially curative surgical resection.', 5),
('d4000000-0000-0000-0000-000000000046', 'A', 'Repeat urgent endoscopy for further attempted endoscopic haemostasis', true, 'Correct. Rebleeding after initial successful endoscopic haemostasis for a high-risk peptic ulcer is generally managed with a further attempt at endoscopic therapy first, which succeeds in most cases and avoids the higher morbidity of surgery or radiological embolisation.', 1),
('d4000000-0000-0000-0000-000000000046', 'B', 'Proceed directly to surgery without a further attempt at endoscopic haemostasis', false, 'Ruled out because repeat endoscopic therapy is attempted first for rebleeding after initial endoscopic success; surgery is reserved for failure of repeat endoscopic therapy.', 2),
('d4000000-0000-0000-0000-000000000046', 'C', 'Increase the PPI infusion dose alone with no further endoscopic intervention', false, 'Ruled out because a confirmed rebleed with haemodynamic and haemoglobin changes requires an attempt at further haemostatic intervention, not simply increased acid suppression.', 3),
('d4000000-0000-0000-0000-000000000046', 'D', 'Urgent CT angiography as the first step in preference to repeat endoscopy', false, 'Ruled out because endoscopy remains first-line for suspected rebleeding after initial endoscopic success; interventional radiology is generally reserved for endoscopic failure or unavailability.', 4),
('d4000000-0000-0000-0000-000000000046', 'E', 'Reassure and observe, attributing the melaena to the passage of previously shed blood', false, 'Ruled out because there is objective evidence of ongoing bleeding (haemoglobin drop, tachycardia), which should be treated as rebleeding requiring active intervention.', 5),
('d4000000-0000-0000-0000-000000000047', 'A', 'Repeat the same first-line triple therapy regimen', false, 'Ruled out because repeating an identical failed regimen risks further failure due to likely clarithromycin resistance having developed or been selected for.', 1),
('d4000000-0000-0000-0000-000000000047', 'B', 'No further eradication attempt needed, as symptoms may have already improved', false, 'Ruled out because persistent H. pylori infection with a duodenal ulcer requires further eradication attempts given ongoing risk of ulcer recurrence/complications and gastric cancer risk if left untreated.', 2),
('d4000000-0000-0000-0000-000000000047', 'C', 'Long-term maintenance PPI therapy alone without further attempts at eradication', false, 'Ruled out because this does not address the underlying infection, which drives ulcer recurrence risk; eradication should still be pursued with an appropriate salvage regimen.', 3),
('d4000000-0000-0000-0000-000000000047', 'D', 'Empirical high-dose triple therapy for a longer duration using the same antibiotics', false, 'Ruled out because simply extending the duration of a regimen containing an antibiotic to which resistance is now likely does not reliably overcome resistance.', 4),
('d4000000-0000-0000-0000-000000000047', 'E', 'Salvage/second-line therapy with a different antibiotic combination not previously used, avoiding clarithromycin', true, 'Correct. After first-line clarithromycin-based triple therapy failure, clarithromycin resistance should be assumed, and salvage regimens (such as bismuth-based quadruple therapy) should avoid clarithromycin rather than repeating the same combination.', 5),
('d4000000-0000-0000-0000-000000000048', 'A', 'Total or partial gastrectomy with lymph node dissection as first-line treatment', false, 'Ruled out because this is reserved for lesions not meeting endoscopic resection criteria; this lesion meets criteria for endoscopic resection with very low risk of lymph node metastasis.', 1),
('d4000000-0000-0000-0000-000000000048', 'B', 'Endoscopic mucosal resection (EMR) rather than ESD', false, 'Ruled out because EMR carries a higher risk of piecemeal resection/incomplete margins for this type of lesion compared with ESD, which allows more reliable en bloc resection important for confirming curative resection.', 2),
('d4000000-0000-0000-0000-000000000048', 'C', 'Endoscopic submucosal dissection (ESD) for en bloc resection of the lesion', true, 'Correct. This lesion meets criteria for endoscopic curative resection (well-differentiated, intramucosal, no ulceration, appropriate size, very low expected risk of lymph node metastasis), and ESD allows reliable en bloc resection with clear margin assessment, avoiding the morbidity of gastrectomy.', 3),
('d4000000-0000-0000-0000-000000000048', 'D', 'Surveillance endoscopy alone with repeat biopsies in 6 months, without resection', false, 'Ruled out because a confirmed early gastric cancer should be resected, given malignant potential for progression, rather than simply monitored.', 4),
('d4000000-0000-0000-0000-000000000048', 'E', 'Systemic chemotherapy as primary treatment', false, 'Ruled out because chemotherapy is not indicated for early-stage, mucosa-confined gastric cancer amenable to curative endoscopic resection.', 5),
('d4000000-0000-0000-0000-000000000049', 'A', 'No gastroprotection needed, as his previous ulcer has already healed', false, 'Ruled out because a prior history of ulcer bleeding combined with dual antiplatelet therapy places him at high risk of recurrent bleeding, for which PPI co-prescription is recommended regardless of healing.', 1),
('d4000000-0000-0000-0000-000000000049', 'B', 'Co-prescribe a PPI for the duration of dual antiplatelet therapy', true, 'Correct. A prior history of peptic ulcer bleeding combined with dual antiplatelet therapy places him at high risk of recurrent bleeding, and PPI co-prescription significantly reduces upper GI bleeding risk in this group, recommended regardless of prior ulcer healing.', 2),
('d4000000-0000-0000-0000-000000000049', 'C', 'Substitute clopidogrel with an H2-receptor antagonist instead of adding a PPI', false, 'Ruled out because H2-receptor antagonists are less effective than PPIs at reducing antiplatelet-associated GI bleeding risk, and clopidogrel should not be stopped as it is required as part of dual antiplatelet therapy post-stenting.', 3),
('d4000000-0000-0000-0000-000000000049', 'D', 'Stop aspirin and continue clopidogrel monotherapy as the main gastroprotective strategy', false, 'Ruled out because both agents are required as dual antiplatelet therapy post-PCI for a defined duration to prevent stent thrombosis; stopping one is a cardiac management decision, not a gastroprotective substitute.', 4),
('d4000000-0000-0000-0000-000000000049', 'E', 'Empirical H. pylori eradication alone without PPI co-prescription, given his prior ulcer history', false, 'Ruled out because he was H. pylori negative at the time of his prior ulcer, so eradication is not indicated; PPI co-prescription is the appropriate strategy for ongoing risk reduction.', 5),
('d4000000-0000-0000-0000-000000000050', 'A', 'Total gastrectomy as first-line management', false, 'Ruled out as excessive for small, multiple, well-differentiated type 1 gastric NETs, which have a generally indolent course; total gastrectomy is reserved for more advanced, larger, or atypical/progressive lesions.', 1),
('d4000000-0000-0000-0000-000000000050', 'B', 'Systemic chemotherapy as first-line treatment', false, 'Ruled out because chemotherapy is not indicated for small, well-differentiated, localised type 1 gastric NETs; its role is in poorly differentiated or metastatic neuroendocrine carcinomas.', 2),
('d4000000-0000-0000-0000-000000000050', 'C', 'No treatment needed; reassure and discharge from follow-up', false, 'Ruled out because, while generally indolent, these tumours still require endoscopic resection of visible lesions and ongoing surveillance given their neoplastic nature.', 3),
('d4000000-0000-0000-0000-000000000050', 'D', 'Endoscopic resection of the larger/dominant lesions with ongoing regular endoscopic surveillance', true, 'Correct. Type 1 gastric neuroendocrine tumours, driven by hypergastrinaemia secondary to achlorhydria in autoimmune atrophic gastritis, generally behave indolently with low metastatic potential, so small lesions are managed with endoscopic resection and surveillance, reserving more radical surgery for larger, more numerous, or progressive/atypical lesions.', 4),
('d4000000-0000-0000-0000-000000000050', 'E', 'Long-term high-dose somatostatin analogue therapy as first-line management, rather than endoscopic resection/surveillance', false, 'Ruled out because somatostatin analogues have a role in some cases of multiple/recurrent disease not amenable to full endoscopic control, but endoscopic resection with surveillance remains standard first-line for this typical presentation.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d4000000-0000-0000-0000-000000000001', 'Timed barium swallow column height and manometric integrated relaxation pressure together provide objective evidence of outflow obstruction after achalasia treatment, and should be checked before attributing recurrent symptoms to reflux or fibrosis alone.', 1),
('d4000000-0000-0000-0000-000000000001', 'POEM allows a fresh, often more extensive myotomy (including onto the gastric side) than repeat surgery, making it an effective salvage option after failed Heller myotomy.', 2),
('d4000000-0000-0000-0000-000000000001', 'Botulinum toxin injection and standard pneumatic dilation provide temporary or lower-efficacy relief and are not preferred as definitive salvage strategies in a fit patient with objectively confirmed persistent obstruction.', 3),
('d4000000-0000-0000-0000-000000000002', 'Eluxadoline acts on gut opioid receptors to reduce stool frequency, urgency and abdominal pain in IBS-D refractory to first-line measures, but is contraindicated without a gallbladder, with alcohol excess, or a history of pancreatitis/sphincter of Oddi dysfunction due to pancreatitis risk.', 1),
('d4000000-0000-0000-0000-000000000002', 'Tricyclic antidepressant intolerance (sedation, anticholinergic effects) is a class effect, so switching to another tricyclic rarely resolves it; a different mechanism of action is preferred.', 2),
('d4000000-0000-0000-0000-000000000002', 'Prolonged or escalating high-dose loperamide carries a risk of cardiac conduction abnormalities and should not be used as an indefinite sole strategy for refractory symptoms.', 3),
('d4000000-0000-0000-0000-000000000003', 'Domperidone (lowest effective dose due to QT prolongation/arrhythmia risk) and metoclopramide (maximum 5-day duration due to extrapyramidal/tardive dyskinesia risk) both carry MHRA-mandated restrictions limiting their long-term use in gastroparesis.', 1),
('d4000000-0000-0000-0000-000000000003', 'Pyloric botulinum toxin injection has not shown benefit over sham in randomised trials and is not recommended for gastroparesis despite endoscopic feasibility.', 2),
('d4000000-0000-0000-0000-000000000003', 'Gastric electrical stimulation is reserved for medication-refractory diabetic gastroparesis, primarily improving nausea and vomiting rather than objectively normalising gastric emptying time.', 3),
('d4000000-0000-0000-0000-000000000004', 'Chronic intestinal pseudo-obstruction mimics mechanical obstruction radiologically but has no anatomical transition point, and surgery does not address the underlying neuromuscular pathology and often worsens outcomes.', 1),
('d4000000-0000-0000-0000-000000000004', 'Nutritional support (enteral, progressing to home parenteral nutrition if needed) via a specialist intestinal failure team is the mainstay for patients with weight loss failing prokinetic/antibiotic therapy.', 2),
('d4000000-0000-0000-0000-000000000004', 'Opioids and high-fibre diets should generally be avoided in severe gut dysmotility as they can precipitate or worsen pseudo-obstructive episodes.', 3),
('d4000000-0000-0000-0000-000000000005', 'Scleroderma oesophageal disease typically causes absent peristalsis with a hypotensive LES, producing severe reflux; this combination makes full (360-degree) fundoplication high-risk for severe dysphagia, unlike in patients with normal peristalsis.', 1),
('d4000000-0000-0000-0000-000000000005', 'Nocturnal acid breakthrough despite twice-daily PPI therapy can be targeted with an adjunctive bedtime H2-receptor antagonist.', 2),
('d4000000-0000-0000-0000-000000000005', 'Interventions that reduce LES tone or wrap the sphincter (POEM, Nissen fundoplication) are inappropriate in aperistaltic reflux disease, risking worsened dysphagia/obstruction rather than benefit.', 3),
('d4000000-0000-0000-0000-000000000006', 'Opioid-induced constipation refractory to optimised conventional laxatives is an indication for a peripherally-acting mu-opioid receptor antagonist such as naloxegol or methylnaltrexone.', 1),
('d4000000-0000-0000-0000-000000000006', 'Opioid switching does not reliably resolve opioid-induced constipation, as it reflects a class effect of mu-opioid receptor agonism in the gut rather than an agent-specific problem.', 2),
('d4000000-0000-0000-0000-000000000006', 'PAMORAs are designed not to cross the blood-brain barrier significantly, preserving central analgesic effect while relieving peripheral (gut) opioid effects.', 3),
('d4000000-0000-0000-0000-000000000007', 'Eosinophilic oesophagitis refractory to topical corticosteroids, with confirmed adherence and persistent histological activity, is an indication for biologic therapy such as dupilumab, alongside continued endoscopic management of any stricture.', 1),
('d4000000-0000-0000-0000-000000000007', 'Endoscopic dilation treats the mechanical consequence (stricture) of eosinophilic oesophagitis but not the underlying inflammatory process; recurrent strictures despite dilation reflect ongoing untreated inflammation.', 2),
('d4000000-0000-0000-0000-000000000007', 'Long-term systemic corticosteroids are avoided for chronic eosinophilic oesophagitis management because of cumulative toxicity; topical steroids, dietary therapy, PPI and biologics are preferred.', 3),
('d4000000-0000-0000-0000-000000000008', 'Fulminant C. difficile infection (hypotension/shock, ileus, or toxic megacolon) requires combination therapy with oral (or per-rectum if ileus present) vancomycin plus IV metronidazole, in addition to early surgical review.', 1),
('d4000000-0000-0000-0000-000000000008', 'Faecal microbiota transplantation has an established role in recurrent CDI after standard antibiotic therapy, not as rescue in acute fulminant colitis.', 2),
('d4000000-0000-0000-0000-000000000008', 'Escalated medical therapy and close monitoring for signs mandating emergency colectomy (perforation, refractory megacolon, multi-organ failure, marked hyperlactataemia) should proceed in parallel.', 3),
('d4000000-0000-0000-0000-000000000009', 'TIPS is indicated for variceal bleeding refractory to, or recurring despite, combined pharmacological (vasoactive drug plus antibiotics) and endoscopic therapy.', 1),
('d4000000-0000-0000-0000-000000000009', 'Balloon tamponade is a temporising bridge to definitive therapy, not definitive treatment, given the risk of mucosal ischaemia/perforation with prolonged inflation.', 2),
('d4000000-0000-0000-0000-000000000009', 'Early TIPS (within 24-72 hours) is increasingly used in high-risk patients with active bleeding at index endoscopy, reflecting evolving practice toward earlier escalation rather than waiting for a second rebleed.', 3),
('d4000000-0000-0000-0000-000000000010', 'Neutropenic enterocolitis (typhlitis) typically presents with fever, right-sided abdominal pain and diarrhoea in profoundly neutropenic patients, with CT showing bowel wall thickening (classically caecal); first-line management is medical.', 1),
('d4000000-0000-0000-0000-000000000010', 'Endoscopy is avoided in suspected neutropenic enterocolitis because of the risk of perforating a friable, ischaemic bowel wall.', 2),
('d4000000-0000-0000-0000-000000000010', 'Surgery is reserved for specific complications: perforation, uncontrolled gastrointestinal bleeding, or clinical deterioration despite maximal medical therapy.', 3),
('d4000000-0000-0000-0000-000000000011', 'Amoebic liver abscess is typically treated medically with metronidazole/tinidazole followed by a luminal agent to eradicate intestinal cyst carriage.', 1),
('d4000000-0000-0000-0000-000000000011', 'Aspiration/drainage is reserved for large abscesses at risk of rupture, those not responding to medical therapy within a few days, diagnostic uncertainty, or left lobe abscesses at risk of pericardial rupture.', 2),
('d4000000-0000-0000-0000-000000000011', 'Relevant travel history combined with positive serology strongly supports amoebic aetiology and should guide specific antimicrobial choice rather than broad-spectrum antibacterial therapy alone.', 3),
('d4000000-0000-0000-0000-000000000012', 'Secondary antibiotic prophylaxis is indicated in all patients recovering from an episode of spontaneous bacterial peritonitis, given a very high one-year recurrence rate without it.', 1),
('d4000000-0000-0000-0000-000000000012', 'Recurrent SBP is a marker of advanced liver disease and poor prognosis, and should prompt assessment for liver transplantation.', 2),
('d4000000-0000-0000-0000-000000000012', 'Primary prophylaxis (for patients who have never had SBP) is reserved for specific high-risk groups, distinct from secondary prophylaxis which applies to anyone post-SBP.', 3),
('d4000000-0000-0000-0000-000000000013', 'The Oxford (Travis) criteria at day 3 of IV corticosteroids identify patients with acute severe UC at high risk of needing colectomy, prompting consideration of rescue therapy.', 1),
('d4000000-0000-0000-0000-000000000013', 'Rescue therapy options for steroid-refractory acute severe UC include infliximab or ciclosporin, chosen based on local expertise and patient factors, with continued surgical involvement throughout.', 2),
('d4000000-0000-0000-0000-000000000013', 'Failure of rescue medical therapy, or signs of toxic megacolon, perforation or haemodynamic compromise at any point, should prompt urgent colectomy rather than further escalation of medical therapy.', 3),
('d4000000-0000-0000-0000-000000000014', 'Boerhaave syndrome (spontaneous oesophageal perforation, classically after forceful vomiting) is a surgical emergency with high mortality if untreated, requiring urgent resuscitation, antimicrobial cover and surgical/thoracic input.', 1),
('d4000000-0000-0000-0000-000000000014', 'CT with oral contrast is the investigation of choice to confirm oesophageal perforation; endoscopy is generally avoided initially due to the risk of extending the perforation.', 2),
('d4000000-0000-0000-0000-000000000014', 'Management depends on stability and contamination: small, contained, stable perforations may be managed conservatively, whereas unstable patients with mediastinal/pleural contamination need urgent surgical repair or endoscopic stenting.', 3),
('d4000000-0000-0000-0000-000000000015', 'Therapeutic drug monitoring distinguishes pharmacokinetic failure (low trough, no/low antibodies - dose intensification may help), immunogenic failure (low trough with high-titre anti-drug antibodies - switching agent is preferred), and mechanistic failure (adequate trough level but no antibodies - switch to a different mechanism of action).', 1),
('d4000000-0000-0000-0000-000000000015', 'High-titre anti-drug antibodies accelerate drug clearance and neutralise efficacy; combination immunomodulator therapy is more effective at preventing immunogenicity when started early rather than reversing it once established.', 2),
('d4000000-0000-0000-0000-000000000015', 'Faecal calprotectin is a useful non-invasive marker of mucosal inflammation and can support decisions around treatment escalation alongside endoscopic and drug-level data.', 3),
('d4000000-0000-0000-0000-000000000016', $x$Vedolizumab's gut-selective mechanism (anti-alpha4beta7 integrin) limits systemic immunosuppression, contributing to a more favourable reproductive safety profile than agents with broader systemic effects.$x$, 1),
('d4000000-0000-0000-0000-000000000016', 'JAK inhibitors carry specific safety warnings around venous thromboembolism, major cardiovascular events and malignancy, and current guidance advises against their use in pregnancy or when planning pregnancy.', 2),
('d4000000-0000-0000-0000-000000000016', 'Escalation to biologic therapy is appropriate after thiopurine failure with objective evidence of ongoing disease activity, before considering surgery, which is reserved for medically refractory disease or specific complications.', 3),
('d4000000-0000-0000-0000-000000000017', $x$Combined medical (anti-TNF) and surgical (seton drainage) therapy is the most effective strategy for complex perianal fistulising Crohn's disease, with anti-TNF agents having the strongest evidence base for fistula healing.$x$, 1),
('d4000000-0000-0000-0000-000000000017', 'Setons should remain in place, draining the tract and preventing recurrent abscess formation, until medical therapy has reduced inflammation, at which point removal can be considered by the surgical team.', 2),
('d4000000-0000-0000-0000-000000000017', 'Antibiotics provide useful adjunctive symptomatic benefit but are not effective as sole long-term therapy and carry cumulative toxicity risks with prolonged use.', 3),
('d4000000-0000-0000-0000-000000000018', $x$Pouchitis is classified as antibiotic-responsive (single course effective), antibiotic-dependent (responds but relapses, requiring maintenance therapy), or antibiotic-refractory (fails to respond, prompting consideration of Crohn's-like disease of the pouch and biologic therapy).$x$, 1),
('d4000000-0000-0000-0000-000000000018', 'Maintenance strategies for antibiotic-dependent pouchitis include probiotics or continuous/rotating low-dose antibiotics, rather than repeated isolated short courses.', 2),
('d4000000-0000-0000-0000-000000000018', $x$Biopsy exclusion of CMV and Crohn's disease of the pouch is important before committing to a chronic antibiotic-dependent pouchitis management pathway, as these require different specific treatments.$x$, 3),
('d4000000-0000-0000-0000-000000000019', 'Maintaining IBD remission throughout pregnancy is associated with better maternal and fetal outcomes than stopping effective therapy, so anti-TNF biologics are generally continued through pregnancy in stable patients.', 1),
('d4000000-0000-0000-0000-000000000019', 'Anti-TNF agents (except certolizumab pegol, which has minimal active placental transfer) cross the placenta, particularly in the third trimester, so live vaccines should be avoided in the infant for the first 6 months of life.', 2),
('d4000000-0000-0000-0000-000000000019', 'Disease flare during pregnancy carries its own risks (preterm delivery, low birth weight, increased postpartum disease activity) that generally outweigh theoretical risks of continued biologic therapy.', 3),
('d4000000-0000-0000-0000-000000000020', $x$Short, focal, accessible, non-penetrating Crohn's strictures can often be managed with endoscopic balloon dilation, avoiding surgical bowel resection and the associated risk of short bowel syndrome with repeated operations.$x$, 1),
('d4000000-0000-0000-0000-000000000020', 'Predominantly fibrotic strictures do not respond to escalation of anti-inflammatory medical therapy alone, as the pathology is structural rather than inflammatory.', 2),
('d4000000-0000-0000-0000-000000000020', 'Surgery remains preferred for long, multiple, angulated strictures or those associated with penetrating complications, where endoscopic dilation is technically difficult or unsafe.', 3),
('d4000000-0000-0000-0000-000000000021', 'Endoscopically resectable, adenoma-like dysplastic lesions with clear margins and no flat dysplasia elsewhere can be managed with continued surveillance rather than colectomy, unlike non-resectable, flat, or multifocal dysplasia.', 1),
('d4000000-0000-0000-0000-000000000021', 'Longstanding extensive ulcerative colitis carries an ongoing field cancerisation risk, so full colonic surveillance must continue even after successful polypectomy.', 2),
('d4000000-0000-0000-0000-000000000021', 'Colectomy is reserved for high-grade dysplasia in flat/invisible mucosa, dysplasia that cannot be completely endoscopically resected, or multifocal dysplasia, reflecting a much higher risk of synchronous or metachronous cancer.', 3),
('d4000000-0000-0000-0000-000000000022', 'Recurrent overt hepatic encephalopathy despite optimal medical therapy (lactulose plus rifaximin) is a recognised indication for liver transplantation assessment, independent of the calculated MELD score.', 1),
('d4000000-0000-0000-0000-000000000022', 'Protein restriction is no longer recommended in cirrhotic patients with hepatic encephalopathy, as malnutrition and sarcopenia independently worsen outcomes; adequate protein intake should be maintained.', 2),
('d4000000-0000-0000-0000-000000000022', 'Neomycin, while historically used, carries significant nephrotoxicity/ototoxicity risk with prolonged use and has been largely superseded by rifaximin for long-term HE prophylaxis.', 3),
('d4000000-0000-0000-0000-000000000023', 'Hepatorenal syndrome-AKI is a diagnosis of exclusion, made after ruling out other causes of AKI and demonstrating failure of renal function to improve despite diuretic withdrawal and albumin-guided volume expansion.', 1),
('d4000000-0000-0000-0000-000000000023', 'First-line pharmacological therapy for HRS-AKI is a vasoconstrictor (terlipressin, or noradrenaline in an intensive care setting) combined with IV albumin.', 2),
('d4000000-0000-0000-0000-000000000023', 'Renal replacement therapy may be used as a bridge to liver transplantation if pharmacological therapy fails, but is not first-line before a trial of vasoconstrictor/albumin therapy.', 3),
('d4000000-0000-0000-0000-000000000024', 'Non-invasive fibrosis staging (FIB-4 as an initial screen, followed by transient elastography or other imaging-based tests) identifies patients with MASLD/NAFLD at risk of advanced fibrosis who need specialist hepatology referral, since ALT correlates poorly with fibrosis severity.', 1),
('d4000000-0000-0000-0000-000000000024', 'Advanced fibrosis (F3) on non-invasive testing warrants intensified management (structured weight loss support, consideration of pharmacological/bariatric options, specialist follow-up), distinct from simple lifestyle advice for early-stage steatosis.', 2),
('d4000000-0000-0000-0000-000000000024', 'Vitamin E has evidence specifically in biopsy-proven MASH in non-diabetic adults, not as a substitute for weight loss and specialist management in diabetic patients with more advanced fibrosis.', 3),
('d4000000-0000-0000-0000-000000000025', 'Relapse after steroid withdrawal is common in autoimmune hepatitis and indicates steroid-dependence; standard management is to reintroduce corticosteroid therapy in combination with an immunomodulator to reinduce remission.', 1),
('d4000000-0000-0000-0000-000000000025', 'Many patients with relapsing autoimmune hepatitis require long-term (often indefinite) combination or low-dose steroid maintenance therapy to sustain remission.', 2),
('d4000000-0000-0000-0000-000000000025', 'Liver transplantation is reserved for autoimmune hepatitis presenting with acute liver failure, or progression to decompensated cirrhosis unresponsive to medical therapy, not straightforward treatable relapses.', 3),
('d4000000-0000-0000-0000-000000000026', $x$Copper chelating agents (penicillamine or trientine) are first-line for symptomatic Wilson's disease, promoting urinary copper excretion; trientine is often preferred due to a better side-effect profile.$x$, 1),
('d4000000-0000-0000-0000-000000000026', 'Zinc salts act more slowly (blocking intestinal copper absorption) and are mainly used for maintenance therapy after initial de-coppering, or in presymptomatic/pregnant patients, rather than initial therapy.', 2),
('d4000000-0000-0000-0000-000000000026', $x$Tetrathiomolybdate is used selectively, particularly to avoid the risk of paradoxical neurological deterioration associated with penicillamine in patients with neurological Wilson's disease.$x$, 3),
('d4000000-0000-0000-0000-000000000027', 'Budd-Chiari syndrome is managed with a stepwise approach: anticoagulation first, then angioplasty/stenting or TIPS for non-responders, with liver transplantation reserved for those failing all other measures or presenting with fulminant failure.', 1),
('d4000000-0000-0000-0000-000000000027', 'Treating the underlying prothrombotic disorder (e.g., cytoreductive therapy for myeloproliferative neoplasms) alongside anticoagulation is important in Budd-Chiari syndrome secondary to a haematological cause.', 2),
('d4000000-0000-0000-0000-000000000027', 'Preserved synthetic liver function at presentation is a favourable prognostic factor and supports starting with the least invasive effective therapy before escalating to interventional options.', 3),
('d4000000-0000-0000-0000-000000000028', 'Refractory ascites (diuretic-intractable due to complications like hyponatraemia/hyperkalaemia, or diuretic-resistant despite maximal therapy) is an indication to consider TIPS in patients without contraindications.', 1),
('d4000000-0000-0000-0000-000000000028', 'TIPS reduces the need for recurrent large-volume paracentesis and can improve quality of life and, in selected patients, survival, compared with repeated LVP alone.', 2),
('d4000000-0000-0000-0000-000000000028', 'Peritoneovenous shunting has largely fallen out of favour due to high complication rates and is not a preferred first-line option where TIPS is available.', 3),
('d4000000-0000-0000-0000-000000000029', 'Refractory coeliac disease type II is characterised by an aberrant, clonal population of intraepithelial lymphocytes and carries a significant risk of progression to enteropathy-associated T-cell lymphoma, unlike type I (polyclonal, better prognosis).', 1),
('d4000000-0000-0000-0000-000000000029', 'Persistent villous atrophy despite confirmed strict dietary adherence should prompt specialist referral to distinguish refractory coeliac disease from simple non-adherence or an alternative diagnosis.', 2),
('d4000000-0000-0000-0000-000000000029', 'Management of refractory coeliac disease type II requires specialist input for staging/lymphoma surveillance and consideration of immunosuppressive or targeted therapies, given the limited efficacy of dietary measures alone.', 3),
('d4000000-0000-0000-0000-000000000030', 'Teduglutide promotes intestinal mucosal adaptation and absorptive capacity, reducing parenteral nutrition/fluid requirements in appropriately selected patients with short bowel syndrome-associated intestinal failure.', 1),
('d4000000-0000-0000-0000-000000000030', 'Intestinal transplantation is reserved for irreversible intestinal failure with life-threatening complications of long-term parenteral nutrition, not simply ongoing PN dependency.', 2),
('d4000000-0000-0000-0000-000000000030', 'Surgical bowel-lengthening procedures are considered in selected cases (more commonly paediatric) with dilated remnant bowel amenable to lengthening, rather than as routine next-step therapy in adult short bowel syndrome.', 3),
('d4000000-0000-0000-0000-000000000031', 'Bile acid diarrhoea (here type 3, post-cholecystectomy) is diagnosed with a SeHCAT scan showing reduced 7-day retention, and treated first-line with a bile acid sequestrant, generally better tolerated as colesevelam than colestyramine.', 1),
('d4000000-0000-0000-0000-000000000031', 'Post-cholecystectomy bile acid diarrhoea occurs due to altered bile acid handling following loss of gallbladder reservoir function, distinct from SIBO or microscopic colitis, which should be specifically excluded as differentials.', 2),
('d4000000-0000-0000-0000-000000000031', 'Loperamide can help symptomatically but does not treat the underlying mechanism, so is used as an adjunct rather than first-line specific therapy once bile acid malabsorption is confirmed.', 3),
('d4000000-0000-0000-0000-000000000032', 'Recurrent SIBO is common when an underlying predisposing cause (structural abnormality, motility disorder, or anatomical blind loop) is not addressed; management should target both the bacterial overgrowth and the underlying driver.', 1),
('d4000000-0000-0000-0000-000000000032', 'Rotating or cyclical antibiotic regimens are often used for recurrent SIBO to reduce the risk of developing antimicrobial resistance compared with repeated identical courses.', 2),
('d4000000-0000-0000-0000-000000000032', 'Prokinetic agents may be considered as adjunctive therapy to reduce recurrence risk in SIBO associated with underlying dysmotility.', 3),
('d4000000-0000-0000-0000-000000000033', $x$Whipple's disease classically presents with weight loss, migratory arthralgia, diarrhoea/steatorrhoea and can involve the CNS; diagnosis is via duodenal biopsy (PAS-positive macrophages) and PCR.$x$, 1),
('d4000000-0000-0000-0000-000000000033', 'Treatment requires an initial induction phase with a CNS-penetrant antibiotic, especially with neurological involvement, followed by prolonged oral maintenance therapy (often at least 1 year) to prevent relapse.', 2),
('d4000000-0000-0000-0000-000000000033', $x$Untreated Whipple's disease is progressive and fatal, and inadequate/short-course treatment risks relapse, particularly with CNS disease which can be difficult to eradicate.$x$, 3),
('d4000000-0000-0000-0000-000000000034', 'Subacute combined degeneration of the spinal cord from B12 deficiency causes a combination of upper motor neuron signs and dorsal column signs due to combined corticospinal tract and dorsal column involvement.', 1),
('d4000000-0000-0000-0000-000000000034', 'Pernicious anaemia requires lifelong parenteral B12 replacement, as oral replacement cannot reliably overcome intrinsic factor-mediated malabsorption.', 2),
('d4000000-0000-0000-0000-000000000034', 'Giving folic acid without first correcting B12 deficiency can precipitate or accelerate neurological deterioration, so B12 status must always be addressed first or alongside folate replacement.', 3),
('d4000000-0000-0000-0000-000000000035', 'A common reason for apparent PERT failure is incorrect administration technique rather than true treatment resistance; enzymes should be taken throughout the meal.', 1),
('d4000000-0000-0000-0000-000000000035', 'Co-prescribing a PPI can improve PERT efficacy by reducing gastric acid-mediated degradation of pancreatic enzymes.', 2),
('d4000000-0000-0000-0000-000000000035', 'Bile acid sequestrants would be inappropriate in pancreatic exocrine insufficiency-related steatorrhoea, as they can further impair fat digestion, unlike their beneficial role in bile acid diarrhoea.', 3),
('d4000000-0000-0000-0000-000000000036', 'The step-up approach (percutaneous or endoscopic drainage first, escalating to minimally invasive necrosectomy if needed, with open necrosectomy reserved for failure) reduces morbidity and mortality compared with primary open surgical necrosectomy.', 1),
('d4000000-0000-0000-0000-000000000036', 'Confirmed infected pancreatic necrosis with clinical deterioration is an indication for source control (drainage), in addition to antibiotics, rather than antibiotics alone.', 2),
('d4000000-0000-0000-0000-000000000036', 'Delaying intervention to allow necrotic collections to become walled-off is preferred where clinically feasible, but should not override the need for timely source control once infection is confirmed and the patient is deteriorating.', 3),
('d4000000-0000-0000-0000-000000000037', 'Type 1 autoimmune pancreatitis classically shows a diffusely enlarged pancreas, elevated serum IgG4, lymphoplasmacytic infiltrate with IgG4-positive cells and storiform fibrosis on biopsy, and often other organ involvement.', 1),
('d4000000-0000-0000-0000-000000000037', 'Oral corticosteroids are first-line induction therapy for autoimmune pancreatitis, typically producing a rapid and dramatic clinical/radiological response, which itself supports the diagnosis.', 2),
('d4000000-0000-0000-0000-000000000037', 'Steroid-sparing agents are reserved for relapsing or steroid-refractory disease/maintenance, not as first-line initial therapy in a treatment-naive presentation.', 3),
('d4000000-0000-0000-0000-000000000038', 'Plastic biliary stents are preferred over metal stents for short-term preoperative decompression in patients proceeding to resectional pancreatic/biliary surgery within a few weeks.', 1),
('d4000000-0000-0000-0000-000000000038', 'Self-expanding metal stents are favoured for longer-term or palliative decompression in unresectable disease due to longer patency, but are not preferred ahead of planned curative surgery.', 2),
('d4000000-0000-0000-0000-000000000038', 'Endoscopic (ERCP) biliary drainage is generally the first-choice route where technically feasible, with percutaneous transhepatic drainage reserved as an alternative when endoscopic access is not possible.', 3),
('d4000000-0000-0000-0000-000000000039', 'A new dominant stricture in PSC always requires evaluation for cholangiocarcinoma, given the significantly elevated lifetime risk of cholangiocarcinoma in PSC.', 1),
('d4000000-0000-0000-0000-000000000039', 'Endoscopic balloon dilation, with or without short-term stenting, is the standard approach to relieve a benign-appearing dominant stricture in PSC, while permanent metal stents are avoided.', 2),
('d4000000-0000-0000-0000-000000000039', 'High-dose ursodeoxycholic acid is not routinely recommended in PSC due to a lack of proven benefit on major outcomes and a signal of harm at high doses in some trials.', 3),
('d4000000-0000-0000-0000-000000000040', 'In chronic pancreatitis with a dilated main pancreatic duct and failure of endoscopic therapy, surgical drainage procedures provide more durable pain relief than repeated endoscopic intervention.', 1),
('d4000000-0000-0000-0000-000000000040', 'Total pancreatectomy (with or without islet autotransplantation) is generally reserved for small-duct disease not amenable to drainage procedures or after failure of drainage surgery, given its higher morbidity.', 2),
('d4000000-0000-0000-0000-000000000040', 'Coeliac plexus block can provide temporary pain relief but is not a durable solution for structural, duct-obstructive chronic pancreatitis pain and should not substitute definitive surgical management when indicated.', 3),
('d4000000-0000-0000-0000-000000000041', 'For mild gallstone pancreatitis without local complications, cholecystectomy should be performed during the index admission (or within 2 weeks) rather than delayed.', 1),
('d4000000-0000-0000-0000-000000000041', 'In severe/necrotising gallstone pancreatitis, cholecystectomy is typically delayed until pancreatic inflammation/necrosis has settled, in contrast to the early approach for mild disease.', 2),
('d4000000-0000-0000-0000-000000000041', 'ERCP with sphincterotomy can reduce recurrent biliary pancreatitis risk in patients unfit for or awaiting cholecystectomy, but does not replace the need for cholecystectomy in fit patients.', 3),
('d4000000-0000-0000-0000-000000000042', 'Rectal NSAIDs, given peri-procedurally, are the best-evidenced pharmacological measure to reduce post-ERCP pancreatitis risk, particularly in high-risk patients.', 1),
('d4000000-0000-0000-0000-000000000042', 'Prophylactic pancreatic duct stent placement is an additional evidence-based measure to reduce post-ERCP pancreatitis in high-risk patients.', 2),
('d4000000-0000-0000-0000-000000000042', 'Antibiotic prophylaxis targets post-ERCP cholangitis risk, not pancreatitis risk, reflecting the distinct pathophysiology and prevention strategies for these two complications.', 3),
('d4000000-0000-0000-0000-000000000043', $x$A visible or nodular lesion within a Barrett's segment showing dysplasia should undergo endoscopic mucosal resection first, both to remove the lesion and to obtain accurate histological staging.$x$, 1),
('d4000000-0000-0000-0000-000000000043', $x$Radiofrequency ablation treats the remaining flat dysplastic Barrett's segment after resection of any visible lesion; endoscopic therapy (EMR plus RFA) is now standard of care for mucosal high-grade dysplasia, replacing oesophagectomy as first-line.$x$, 2),
('d4000000-0000-0000-0000-000000000043', 'Oesophagectomy is reserved for endoscopically unresectable disease, or histological evidence of submucosal invasion/lymph node involvement following staging.', 3),
('d4000000-0000-0000-0000-000000000044', 'pH-impedance monitoring performed on PPI therapy in refractory cases can identify ongoing weakly acidic or non-acid reflux as the cause of symptoms despite adequate acid suppression, distinguishing true PPI-refractory reflux from functional heartburn.', 1),
('d4000000-0000-0000-0000-000000000044', 'A positive symptom association probability with reflux episodes (acid or non-acid) on impedance-pH testing supports a diagnosis of true reflux disease, for which anti-reflux surgery may be considered when refractory to maximal medical therapy.', 2),
('d4000000-0000-0000-0000-000000000044', 'Functional heartburn is defined by a negative correlation between symptoms and any type of reflux episode with normal reflux burden, and is managed differently rather than with anti-reflux surgery.', 3),
('d4000000-0000-0000-0000-000000000045', 'Zollinger-Ellison syndrome should be suspected with multiple/refractory/atypically located peptic ulcers, especially with diarrhoea improving on acid suppression, and confirmed with fasting gastrin and gastric pH measurement.', 1),
('d4000000-0000-0000-0000-000000000045', 'After biochemical confirmation, localisation imaging is required to assess for resectable disease and exclude metastases, before considering surgery.', 2),
('d4000000-0000-0000-0000-000000000045', 'All patients with a new gastrinoma diagnosis should be screened for MEN1 regardless of family history, as this changes surgical planning and follow-up.', 3),
('d4000000-0000-0000-0000-000000000046', 'Rebleeding after initial successful endoscopic haemostasis for a high-risk peptic ulcer is generally managed with a further attempt at endoscopic therapy first.', 1),
('d4000000-0000-0000-0000-000000000046', 'Interventional radiology or surgery is reserved for failure of a second endoscopic attempt, or when endoscopic access/expertise is not available.', 2),
('d4000000-0000-0000-0000-000000000046', 'Ongoing high-dose IV PPI therapy is an important adjunct throughout, but does not substitute for mechanical haemostatic intervention when there is evidence of active/recurrent bleeding.', 3),
('d4000000-0000-0000-0000-000000000047', 'After first-line clarithromycin-based triple therapy failure, clarithromycin resistance should be assumed, and salvage regimens should avoid clarithromycin rather than repeating the same combination.', 1),
('d4000000-0000-0000-0000-000000000047', 'Confirmation of eradication requires an appropriate washout period off PPI and antibiotics to avoid false-negative results.', 2),
('d4000000-0000-0000-0000-000000000047', 'Persistent H. pylori infection in the context of peptic ulcer disease carries ongoing risks of ulcer recurrence, bleeding, and longer-term gastric malignancy, so repeated eradication attempts with an adjusted regimen are warranted.', 3),
('d4000000-0000-0000-0000-000000000048', 'Early gastric cancers meeting specific criteria (differentiated histology, intramucosal, no ulceration, appropriate size) carry a very low risk of lymph node metastasis and can be managed curatively with endoscopic resection rather than gastrectomy.', 1),
('d4000000-0000-0000-0000-000000000048', 'Endoscopic submucosal dissection allows more reliable en bloc resection with clear margin assessment compared with EMR, important for confirming curative resection of early gastric cancer.', 2),
('d4000000-0000-0000-0000-000000000048', 'Gastrectomy with lymphadenectomy is reserved for lesions not meeting endoscopic curative resection criteria (deeper invasion, poor differentiation, ulceration with larger size, or nodal involvement).', 3),
('d4000000-0000-0000-0000-000000000049', 'Patients with a prior history of peptic ulcer bleeding who require antiplatelet or NSAID therapy are at high risk of recurrent GI bleeding and should receive PPI co-prescription regardless of documented ulcer healing.', 1),
('d4000000-0000-0000-0000-000000000049', 'PPIs are more effective than H2-receptor antagonists at reducing antiplatelet/NSAID-associated upper GI bleeding risk in high-risk patients.', 2),
('d4000000-0000-0000-0000-000000000049', 'Decisions about the antiplatelet regimen itself are made by cardiology based on stent/ischaemic risk; gastroprotective strategy is applied alongside the prescribed antiplatelet regimen rather than altering it.', 3),
('d4000000-0000-0000-0000-000000000050', 'Type 1 gastric neuroendocrine tumours arise from ECL cell hyperplasia driven by chronic hypergastrinaemia secondary to achlorhydria in autoimmune atrophic gastritis/pernicious anaemia, and generally behave indolently, unlike type 3 (sporadic) gastric NETs which are more aggressive.', 1),
('d4000000-0000-0000-0000-000000000050', 'Small type 1 gastric NETs are managed with endoscopic resection of visible lesions and ongoing endoscopic surveillance, reserving antrectomy or gastrectomy for larger, more numerous, or progressive disease.', 2),
('d4000000-0000-0000-0000-000000000050', 'Patients with pernicious anaemia require ongoing gastroscopic surveillance given their increased risk of both gastric neuroendocrine tumours and gastric adenocarcinoma related to chronic atrophic gastritis.', 3);
